"use strict";
/* 国民年金法 追加問題(X6/XT6/XS6)。ID恒久。 */
(window.QPARTS = window.QPARTS || []).push(
 {id:"X6-001",s:6,q:"第2号被保険者の被扶養配偶者であっても、その者自身が厚生年金保険の被保険者であるときは、第3号被保険者ではなく第2号被保険者となる。",a:true,e:"法7条1項3号。第3号被保険者は「第2号被保険者である者を除く」とされ、第2号への該当が優先する。",topic:"被保険者"},
 {id:"X6-002",s:6,q:"第3号被保険者には国内居住要件がないため、第2号被保険者の被扶養配偶者であれば、海外に居住していても当然に第3号被保険者となる。",a:false,e:"法7条1項3号。令和2年4月から第3号にも原則として国内居住要件がある。留学や海外赴任への同行など日本に生活の基礎がある者は例外。",topic:"被保険者"},
 {id:"X6-003",s:6,q:"厚生年金保険法に基づく老齢給付等を受けることができる者は、日本国内に住所を有する20歳以上60歳未満であっても、第1号被保険者とならない。",a:true,e:"法7条1項1号括弧書。老齢給付等を受けることができる者は第1号から除かれる。この者は任意加入被保険者となることができる(附則5条)。",topic:"被保険者"},
 {id:"X6-004",s:6,q:"20歳以上60歳未満の者が日本国内に住所を有するに至ったときは、その日に第1号被保険者の資格を取得する。",a:true,e:"法8条。国内に住所を有するに至った日に取得する。海外から帰国した日本人や来日した外国人が典型例。",topic:"被保険者"},
 {id:"X6-005",s:6,q:"第1号被保険者が日本国内に住所を有しなくなった場合、その日に更に第2号被保険者に該当するに至ったときであっても、資格の喪失日はその翌日となる。",a:false,e:"法9条。国内住所喪失は原則翌日喪失だが、その日に更に第2号・第3号に該当するに至ったときは「その日」に喪失する。",topic:"被保険者"},
 {id:"X6-006",s:6,q:"第2号被保険者の被扶養配偶者(20歳未満)が20歳に達したときは、その日に第3号被保険者の資格を取得する。",a:true,e:"法8条。20歳到達日に資格を取得する。第2号の被扶養配偶者であれば第1号ではなく第3号として取得する。",topic:"被保険者"},
 {id:"X6-007",s:6,q:"被保険者期間を計算する場合には、被保険者の資格を取得した日の属する月の翌月から、資格を喪失した日の属する月までを算入する。",a:false,e:"法11条1項。資格を取得した日の属する月から、資格を喪失した日の属する月の前月までを算入する。月単位で計算する。",topic:"被保険者"},
 {id:"X6-008",s:6,q:"同一の月において被保険者の種別に変更があったときは、その月は変更後の種別の被保険者であった月とみなされる。",a:true,e:"法11条の2。同一月に2回以上の種別変更があったときは、最後の種別の被保険者であった月とみなす。",topic:"被保険者"},
 {id:"X6-009",s:6,q:"被保険者がその資格を取得した日の属する月にその資格を喪失したときは、原則として、その月を1か月として被保険者期間に算入する。",a:true,e:"法11条1項ただし書。いわゆる月内得喪は1か月算入。ただし、その月に更に資格を取得したときはこの限りでない。",topic:"被保険者"},
 {id:"X6-010",s:6,q:"被保険者の資格を喪失した後、更にその資格を取得した者については、前後の被保険者期間は合算されない。",a:false,e:"法11条2項。資格を喪失した後に再取得した者については、前後の被保険者期間を合算する。",topic:"被保険者"},
 {id:"X6-011",s:6,q:"任意加入被保険者は、厚生労働大臣に加入の申出をした日に被保険者の資格を取得する。",a:true,e:"法附則5条。申出をした日に取得する。国内居住の60歳以上65歳未満の者、海外在住の日本人などが対象。",topic:"被保険者"},
 {id:"X6-012",s:6,q:"日本国内に住所を有する60歳以上65歳未満の者は、厚生年金保険法に基づく老齢給付等を受けることができる場合には、任意加入被保険者となることができない。",a:false,e:"法附則5条。国内居住の60歳以上65歳未満の者は、老齢給付等の受給の有無を問わず任意加入できる(第2号等を除く)。",topic:"被保険者"},
 {id:"X6-013",s:6,q:"任意加入の申出は、正当な事由がある場合を除き、口座振替により保険料を納付する旨の申出とあわせて行わなければならない。",a:true,e:"法附則5条。任意加入の申出は原則として口座振替納付の申出とあわせて行う。",topic:"被保険者"},
 {id:"X6-014",s:6,q:"任意加入被保険者は、いつでも厚生労働大臣に申し出て、被保険者の資格を喪失することができる。",a:true,e:"法附則5条。申出が受理された日に喪失する。免除制度の適用がない代わりに脱退の自由が認められている。",topic:"被保険者"},
 {id:"X6-015",s:6,q:"日本国内に住所を有する任意加入被保険者(特例任意加入被保険者を除く)は、70歳に達した日に被保険者の資格を喪失する。",a:false,e:"法附則5条。任意加入被保険者は65歳到達日に喪失する。70歳まで加入できるのは昭和40年4月1日以前生まれの特例任意加入被保険者。",topic:"被保険者"},
 {id:"X6-016",s:6,q:"特例任意加入被保険者は、申出により付加保険料を納付することができる。",a:false,e:"平成6年改正法附則11条等。特例任意加入は受給資格期間を満たすための制度であり、付加保険料は納付できない。",topic:"被保険者"},
 {id:"X6-017",s:6,q:"任意加入被保険者(特例任意加入被保険者を除く)は、申出により付加保険料を納付することができる。",a:true,e:"法附則5条・法87条の2。任意加入被保険者は第1号被保険者とみなされ、付加保険料を納付できる。",topic:"被保険者"},
 {id:"X6-018",s:6,q:"厚生年金保険の被保険者である60歳以上65歳未満の者は、国民年金の任意加入被保険者となることができる。",a:false,e:"法附則5条。任意加入被保険者となれるのは第2号・第3号被保険者以外の者。厚年被保険者(第2号)は任意加入できない。",topic:"被保険者"},
 {id:"X6-019",s:6,q:"特例任意加入被保険者となることができるのは、65歳以上70歳未満の期間に限られる。",a:true,e:"平成6年・平成16年改正法附則。昭和40年4月1日以前生まれで受給資格期間を満たさない者が対象。70歳到達日に資格を喪失する。",topic:"被保険者"},
 {id:"X6-020",s:6,q:"第2号被保険者には年齢要件がないため、18歳で厚生年金保険の被保険者となった者も第2号被保険者となる。",a:true,e:"法7条1項2号。厚年被保険者は年齢を問わず第2号(65歳以上で老齢給付の受給権がある者を除く)。20歳前の期間は老齢基礎年金上は合算対象期間。",topic:"被保険者"},
 {id:"X6-021",s:6,q:"65歳以上で老齢基礎年金の受給権を有する厚生年金保険の被保険者に扶養されている50歳の配偶者は、第3号被保険者となる。",a:false,e:"法7条1項3号・附則3条。第3号は「第2号被保険者の」被扶養配偶者。65歳以上の老齢給付受給権者は第2号でないため、その配偶者は第1号となる。",topic:"被保険者"},
 {id:"X6-022",s:6,q:"第2号被保険者の配偶者が第3号被保険者となるためには、婚姻の届出をしている必要があり、事実上婚姻関係と同様の事情にある者は第3号被保険者となれない。",a:false,e:"法5条。配偶者・夫・妻には、婚姻の届出をしていないが事実上婚姻関係と同様の事情にある者を含む。事実婚でも第3号になりうる。",topic:"被保険者"},
 {id:"X6-023",s:6,q:"日本国籍を有しない者であって、医療目的で日本に滞在する在留資格「特定活動」の者など厚生労働省令で定める者は、第1号被保険者から除かれる。",a:true,e:"法7条1項1号・則。医療滞在や観光・保養目的の長期滞在者は適用除外。それ以外の外国人は国籍を問わず第1号となりうる。",topic:"被保険者"},
 {id:"X6-024",s:6,q:"第1号被保険者が厚生年金保険の被保険者となったときは、その日に第2号被保険者となる。",a:true,e:"法8条・9条。厚年被保険者の資格取得日に第2号の資格を取得し、第1号からの種別変更となる。",topic:"被保険者"},
 {id:"X6-025",s:6,q:"日本国内に住所を有する20歳以上60歳未満の第1号被保険者が、厚生年金保険法に基づく老齢給付等を受けることができる者となったときは、第1号被保険者の資格を喪失する。",a:true,e:"法9条。老齢給付等を受けることができる者は第1号から除外されるため資格を喪失する。引き続き加入するには任意加入の申出が必要。",topic:"被保険者"},
 {id:"X6-026",s:6,q:"第3号被保険者が60歳に達したときは、配偶者が第2号被保険者であっても、その日に第3号被保険者の資格を喪失する。",a:true,e:"法7条1項3号・9条。第3号には20歳以上60歳未満の年齢要件があり、60歳到達日に喪失する。",topic:"被保険者"},
 {id:"X6-027",s:6,q:"第1号被保険者は、資格の取得・喪失や種別の変更に関する事項を、原則として14日以内に市町村長(特別区の区長を含む)に届け出なければならない。",a:true,e:"法12条1項・則。第1号の届出先は市町村長。第3号の届出は配偶者の事業主等を経由して厚生労働大臣に行う。",topic:"届出・原簿"},
 {id:"X6-028",s:6,q:"第1号被保険者の属する世帯の世帯主は、被保険者に代わって資格の取得等の届出をすることができる。",a:true,e:"法12条2項。世帯主は被保険者に代わって届出をすることができる。世帯主は保険料の連帯納付義務も負う。",topic:"届出・原簿"},
 {id:"X6-029",s:6,q:"第3号被保険者の届出が遅れた場合、原則として、届出が行われた日の属する月の前々月までの2年間より前の期間は保険料納付済期間に算入されない。",a:true,e:"法附則7条の3第1項。遡りは2年間に限られる。やむを得ない事由があると認められれば特例届出により算入される(同2項)。",topic:"届出・原簿"},
 {id:"X6-030",s:6,q:"第3号被保険者の届出が遅れたために保険料納付済期間に算入されない期間についても、届出の遅滞にやむを得ない事由があると認められるときは、厚生労働大臣に届け出ることにより保険料納付済期間に算入される。",a:true,e:"法附則7条の3第2項。平成17年4月から設けられた特例届出。遅滞の期間も保険料納付済期間に算入され、老齢基礎年金の額に反映される。",topic:"届出・原簿"},
 {id:"X6-031",s:6,q:"令和4年4月以降も、新たに国民年金の被保険者となった者には国民年金手帳が交付される。",a:false,e:"令和2年改正法により国民年金手帳は令和4年4月に廃止された。新たに資格を取得した者には基礎年金番号通知書が送付される。",topic:"届出・原簿"},
 {id:"X6-032",s:6,q:"被保険者又は被保険者であった者は、国民年金原簿に記録された自己の記録が事実でない等と思料するときは、厚生労働大臣に対し訂正の請求をすることができる。",a:true,e:"法14条の2。年金記録の訂正請求制度。厚生労働大臣は請求に基づき訂正の要否を決定する。",topic:"届出・原簿"},
 {id:"X6-033",s:6,q:"厚生労働大臣は、被保険者に対し、保険料納付の実績や将来の給付に関する情報を、被保険者から請求があった場合に限り通知する。",a:false,e:"法14条の5。厚生労働大臣は、請求の有無にかかわらず、分かりやすい形で通知する(ねんきん定期便)。",topic:"届出・原簿"},
 {id:"X6-034",s:6,q:"厚生労働大臣は、国民年金原簿を備え、被保険者の氏名、資格の取得及び喪失、種別の変更、保険料の納付状況、基礎年金番号などを記録する。",a:true,e:"法14条。国民年金原簿は厚生労働大臣が備える。記録の訂正請求は法14条の2。",topic:"届出・原簿"},
 {id:"X6-035",s:6,q:"第2号被保険者は、第2号被保険者の資格を取得したとき、国民年金法上の資格取得届を本人が市町村長に提出しなければならない。",a:false,e:"法12条。本人の市町村長への届出義務は第1号被保険者に関するもの。第2号の資格は厚年の被保険者資格に連動し、事業主の厚年の届出で把握される。",topic:"届出・原簿"},
 {id:"X6-036",s:6,q:"第1号被保険者の毎月の保険料は、翌月末日までに納付しなければならない。",a:true,e:"法91条。納期限は翌月末日。保険料徴収権の2年の時効は納期限の翌日から進行する。",topic:"保険料"},
 {id:"X6-037",s:6,q:"前納された保険料は、前納をした日に、前納に係る期間の各月の保険料が納付されたものとみなされる。",a:false,e:"法93条3項。前納に係る期間の各月が経過した際に、それぞれその月の保険料が納付されたものとみなす。",topic:"保険料"},
 {id:"X6-038",s:6,q:"保険料を前納した後、前納に係る期間の経過前に被保険者の資格を喪失した場合には、未経過期間に係る前納保険料は請求により還付される。",a:true,e:"法93条・令9条。資格喪失や第2号・第3号への種別変更等のときは、未経過期間分が還付される。",topic:"保険料"},
 {id:"X6-039",s:6,q:"前納すべき額は、前納に係る期間の各月の保険料の合計額から、政令で定める額を控除した額である。",a:true,e:"法93条2項・令。年4分の利率による複利現価法で割り引いた額を控除する。",topic:"保険料"},
 {id:"X6-040",s:6,q:"被保険者は、口座振替により保険料を納付することを厚生労働大臣に申し出ることができ、厚生労働大臣は納付が確実であり有利と認められるときに限り承認することができる。",a:true,e:"法92条の2。口座振替納付の承認。任意加入の場合は原則として口座振替による(附則5条)。",topic:"保険料"},
 {id:"X6-041",s:6,q:"被保険者は、厚生労働大臣が指定する指定代理納付者(クレジットカード会社等)に保険料を立て替えて納付させることを申し出ることができる。",a:true,e:"法92条の2の2。指定代理納付者による納付(クレジットカード納付)。口座振替・コンビニ納付と並ぶ納付手段の一つ。",topic:"保険料"},
 {id:"X6-042",s:6,q:"保険料の納付に関する事務は、コンビニエンスストアや国民年金基金などに委託することは認められていない。",a:false,e:"法92条の3。国民年金基金、厚生労働大臣が指定する納付受託者(コンビニ等)への納付委託が認められている。",topic:"保険料"},
 {id:"X6-043",s:6,q:"第1号被保険者の保険料は、被保険者の前年の所得に応じて定められる。",a:false,e:"法87条。第1号の保険料は所得にかかわらず定額。所得の低い者には免除制度等で対応する。",topic:"保険料"},
 {id:"X6-044",s:6,q:"第1号被保険者の保険料の納付義務は、被保険者が60歳に達した日の属する月の分まで生じる。",a:false,e:"法87条2項・11条1項。60歳到達日に資格を喪失し、喪失月の前月までが被保険者期間となるため、60歳到達月の前月分まで。",topic:"保険料"},
 {id:"X6-045",s:6,q:"督促状に指定した期限までに保険料を完納したときは、延滞金は徴収されない。",a:true,e:"法97条。延滞金は指定期限までに完納しない場合に、納期限の翌日から完納日の前日までの期間について課される。",topic:"保険料"},
 {id:"X6-046",s:6,q:"延滞金の割合は、法律上、年14.6%(納期限の翌日から3月を経過する日までの期間は年7.3%)と定められている。",a:true,e:"法97条1項。実際には租税特別措置法の特例基準割合等により軽減された割合が適用される。",topic:"保険料"},
 {id:"X6-047",s:6,q:"厚生労働大臣は、保険料を滞納する者について、国税滞納処分の例によって処分することができるほか、市町村に対してその処分を請求することもできる。",a:true,e:"法96条4項。請求を受けた市町村は市町村税の例により処分することができる。",topic:"保険料"},
 {id:"X6-048",s:6,q:"厚生労働大臣は、一定の要件に該当する滞納者について、滞納処分等に係る権限を財務大臣に委任することができる。",a:true,e:"法109条の5。財産隠蔽のおそれがあるなど悪質な場合に、財務大臣(さらに国税庁長官)に委任して強制徴収を行う。",topic:"保険料"},
 {id:"X6-049",s:6,q:"保険料その他の徴収金についての督促には、時効の更新の効力はない。",a:false,e:"法102条。保険料その他の徴収金についての督促(法96条1項)は、時効の更新の効力を有する。",topic:"保険料"},
 {id:"X6-050",s:6,q:"保険料その他の徴収金を徴収し、又はその還付を受ける権利は、2年を経過したときは時効によって消滅する。",a:true,e:"法102条4項。保険料の徴収権・還付請求権は2年。死亡一時金を受ける権利も2年。年金給付を受ける権利は5年。",topic:"保険料"},
 {id:"X6-051",s:6,q:"保険料を徴収する権利が時効によって消滅した期間は、その後に保険料を納付して保険料納付済期間とすることは原則としてできない。",a:true,e:"法102条4項。2年の時効完成後は原則納付できず、未納期間として確定する(過去の後納制度は時限措置で終了)。",topic:"保険料"},
 {id:"X6-052",s:6,q:"第2号被保険者及び第3号被保険者は個別に国民年金の保険料を納付せず、その基礎年金の費用は、厚生年金保険の実施者たる政府及び実施機関たる共済組合等が納付する基礎年金拠出金により賄われる。",a:true,e:"法94条の2。第2号・第3号は個別に国民年金保険料を納付せず、基礎年金拠出金により費用を負担する。",topic:"保険料"},
 {id:"X6-053",s:6,q:"世帯主が連帯して納付する義務を負うのは、世帯に属する被保険者が20歳未満である場合に限られる。",a:false,e:"法88条2項。世帯主は世帯に属する被保険者の保険料を、被保険者の年齢にかかわらず連帯して納付する義務を負う。",topic:"保険料"},
 {id:"X6-054",s:6,q:"法定免除に該当する者は、法定免除の事由に該当するに至った日の属する月から、該当しなくなる日の属する月の前月まで保険料が免除される。",a:false,e:"法89条1項。該当するに至った日の属する月の「前月」から、該当しなくなる日の属する月「まで」が免除される。",topic:"保険料の免除"},
 {id:"X6-055",s:6,q:"法定免除の対象となる者であっても、本人が申出をすれば、法定免除期間の保険料を納付することができる。",a:true,e:"法89条2項。平成26年4月から、申出により法定免除期間の保険料(前納を含む)を納付できるようになった。",topic:"保険料の免除"},
 {id:"X6-056",s:6,q:"国立ハンセン病療養所等の施設に入所している第1号被保険者は、申請免除の対象であり、法定免除の対象とはならない。",a:false,e:"法89条1項3号。国立ハンセン病療養所等への入所者は法定免除の対象。生活扶助受給者、障害基礎年金等(1・2級)の受給権者も同様。",topic:"保険料の免除"},
 {id:"X6-057",s:6,q:"障害厚生年金の受給権者であっても、障害等級3級に該当する程度の障害の状態にとどまる者(2級以上に該当したことがない者)は、障害を理由とする法定免除の対象とならない。",a:true,e:"法89条1項1号・令。法定免除の対象は障害等級2級以上に該当する障害基礎年金・障害厚生年金等の受給権者。",topic:"保険料の免除"},
 {id:"X6-058",s:6,q:"20歳前傷病による障害基礎年金の受給権者は、保険料を納付していない者に対する給付であるため、保険料の法定免除の対象とならない。",a:false,e:"法89条1項1号。20歳前傷病によるものを含め、障害基礎年金(1・2級)の受給権者は法定免除の対象となる。",topic:"保険料の免除"},
 {id:"X6-059",s:6,q:"申請全額免除の所得審査においては、被保険者本人の所得のみが審査対象となり、世帯主や配偶者の所得は問われない。",a:false,e:"法90条1項。申請免除は本人・配偶者・世帯主のいずれもが要件を満たすことが必要。本人のみで判定するのは学生納付特例。",topic:"保険料の免除"},
 {id:"X6-060",s:6,q:"生活保護法による生活扶助以外の扶助(医療扶助等)を受けている第1号被保険者は、申請全額免除の事由に該当する。",a:true,e:"法90条1項2号。生活扶助は法定免除の事由、それ以外の扶助は申請免除の事由となる。",topic:"保険料の免除"},
 {id:"X6-061",s:6,q:"地方税法に定める障害者又は寡婦であって前年の所得が一定額以下の者は、法定免除の対象となる。",a:false,e:"法90条1項3号。障害者・寡婦等で所得が政令で定める額以下の場合は、申請全額免除の事由であり法定免除ではない。",topic:"保険料の免除"},
 {id:"X6-062",s:6,q:"失業等により保険料の納付が困難な場合の申請免除では、失業した本人の所得を除外して審査を受けることができる。",a:true,e:"法90条1項・則。失業等の事由があるときは本人の前年所得を審査対象から除外する(いわゆる退職特例)。世帯主・配偶者の所得は審査される。",topic:"保険料の免除"},
 {id:"X6-063",s:6,q:"学生納付特例の適用を受けることができる学生等であっても、所得が低ければ申請全額免除を選択することができる。",a:false,e:"法90条1項括弧書。学生等である期間は申請免除(全額・一部)の対象から除かれ、学生は学生納付特例によることになる。",topic:"保険料の免除"},
 {id:"X6-064",s:6,q:"保険料の一部免除の承認を受けた者が残りの保険料を納付しなかった場合、その期間は保険料免除期間とはならず未納期間として扱われる。",a:true,e:"法5条・90条の2。一部免除期間は、残余の額を納付した場合に限り保険料免除期間となる。",topic:"保険料の免除"},
 {id:"X6-065",s:6,q:"保険料の半額免除を受けることができる所得基準は、全額免除の所得基準よりも低い額に設定されている。",a:false,e:"法90条の2・令。一部免除は全額免除より所得基準が高く(緩く)設定され、所得が上がるにつれ4分の3免除・半額免除・4分の1免除と免除割合が下がる。",topic:"保険料の免除"},
 {id:"X6-066",s:6,q:"第1号被保険者としての保険料納付済期間には、保険料の一部免除を受けた期間は含まれず、その期間は保険料免除期間に分類される。",a:true,e:"法5条1項括弧書・2項。一部免除期間(残余納付済)は保険料免除期間であり、納付済期間ではない。",topic:"保険料の免除"},
 {id:"X6-067",s:6,q:"申請免除の所得審査において、1月から6月までの月分の保険料については、前々年の所得により審査される。",a:true,e:"法90条1項・則。前年の所得で判定するが、1月から6月までの月分は前々年の所得による。承認期間は7月から翌年6月まで。",topic:"保険料の免除"},
 {id:"X6-068",s:6,q:"学生納付特例の所得審査は学生本人の所得のみで行われ、世帯主の所得は問われない。",a:true,e:"法90条の3。学生納付特例は本人の所得のみで判定するため、親の所得が高くても利用できる。",topic:"保険料の免除"},
 {id:"X6-069",s:6,q:"学生納付特例の対象となる学生等には、大学の夜間部や通信制課程の学生は含まれない。",a:false,e:"法90条の3・令。大学等の夜間・定時制・通信制課程の学生も対象に含まれる。",topic:"保険料の免除"},
 {id:"X6-070",s:6,q:"学生納付特例の承認期間は、原則として4月から翌年3月までを単位とする。",a:true,e:"法90条の3・則。学生納付特例は年度単位(4月〜翌3月)、申請全額免除や納付猶予は7月〜翌6月が単位。",topic:"保険料の免除"},
 {id:"X6-071",s:6,q:"保険料納付猶予制度は、50歳未満の第1号被保険者を対象とする時限的な措置である。",a:true,e:"平成16年改正法附則19条・平成26年改正法附則14条。本人と配偶者の所得で判定する。世帯主の所得は問わない。",topic:"保険料の免除"},
 {id:"X6-072",s:6,q:"保険料納付猶予の承認を受けた期間は、追納しなくても、老齢基礎年金の額にその2分の1が反映される。",a:false,e:"平成16年改正法附則19条・法27条。納付猶予期間は受給資格期間に算入されるが、追納しない限り年金額には反映されない。",topic:"保険料の免除"},
 {id:"X6-073",s:6,q:"学生納付特例期間や納付猶予期間は、障害基礎年金・遺族基礎年金の保険料納付要件の判定において、保険料免除期間として扱われる。",a:true,e:"法5条2項・30条等。3分の2要件の計算では保険料納付済期間とあわせて算入される。",topic:"保険料の免除"},
 {id:"X6-074",s:6,q:"保険料の申請免除の要件に該当していても、免除の申請をしなかった期間は未納期間として扱われる。",a:true,e:"法90条。申請免除は申請と承認によって効果が生じる。申請は2年1か月前までの期間について遡って行うことができる。",topic:"保険料の免除"},
 {id:"X6-075",s:6,q:"保険料全額免除又は納付猶予の承認を受けた者は、翌年度以降も継続して審査を受ける旨をあらかじめ申し出ることにより、毎年度の申請を省略することができる。",a:true,e:"法90条・則。全額免除・納付猶予には継続審査の仕組みがある。一部免除は毎年度の申請が必要。",topic:"保険料の免除"},
 {id:"X6-076",s:6,q:"天災により財産に大きな被害を受けたことは、保険料の申請免除の事由とはならない。",a:false,e:"法90条1項・則。所得基準のほか、震災・風水害等の災害や失業等により納付が困難な場合も申請免除の事由となる。",topic:"保険料の免除"},
 {id:"X6-077",s:6,q:"産前産後期間の保険料免除は、厚生労働大臣の承認を要する申請免除の一種であり、所得要件が設けられている。",a:false,e:"法88条の2。産前産後免除は届出により適用され、所得要件はない。免除期間は保険料納付済期間として扱われる。",topic:"保険料の免除"},
 {id:"X6-078",s:6,q:"産前産後期間の保険料免除の対象となる出産には、妊娠85日以上の死産・流産・早産も含まれる。",a:true,e:"法88条の2・則。妊娠85日(4か月)以上の出産であれば、生産・死産・流産等を問わず対象となる。",topic:"保険料の免除"},
 {id:"X6-079",s:6,q:"産前産後期間の保険料免除を受けている第1号被保険者は、国民年金基金の加入員となることができる。",a:true,e:"法127条1項・88条の2。産前産後免除期間は納付済期間扱いであり、基金加入や付加保険料の納付が可能。",topic:"保険料の免除"},
 {id:"X6-080",s:6,q:"産前産後期間の保険料免除は、第1号被保険者だけでなく第3号被保険者にも適用される。",a:false,e:"法88条の2。対象は第1号被保険者。第3号は保険料を個別に負担せず納付済期間とされるため、この制度の対象外。",topic:"保険料の免除"},
 {id:"X6-081",s:6,q:"老齢基礎年金の受給権者であっても、免除を受けた月から10年以内であれば保険料を追納することができる。",a:false,e:"法94条1項ただし書。老齢基礎年金の受給権者は追納できない。受給権取得時に年金額が確定するため。",topic:"追納"},
 {id:"X6-082",s:6,q:"追納は、原則として先に経過した月の分から順次行うものとされている。",a:true,e:"法94条2項。先に経過した月の分から順次行うのが原則(学生納付特例期間等に関する例外あり)。",topic:"追納"},
 {id:"X6-083",s:6,q:"追納が行われたときは、追納が行われた日に、追納に係る月の保険料が納付されたものとみなされる。",a:true,e:"法94条4項。遡って本来の納期に納付されたものとはされないため、障害・遺族の納付要件を事後に満たす手段にはならない。",topic:"追納"},
 {id:"X6-084",s:6,q:"免除を受けた月の属する年度の翌年度中に追納する場合であっても、承認当時の保険料額に政令で定める額が加算される。",a:false,e:"法94条3項・令。加算額が付くのは免除を受けた年度の翌年度から起算して3年度目以降に追納する場合。翌年度中なら加算されない。",topic:"追納"},
 {id:"X6-085",s:6,q:"産前産後期間の免除を受けた期間の保険料は、将来の年金額を増やすために追納することができる。",a:false,e:"法94条1項。産前産後免除期間は保険料納付済期間とされるため追納の対象外。追納できるのは法定・申請免除、学生納付特例、納付猶予の期間。",topic:"追納"},
 {id:"X6-086",s:6,q:"納付猶予の承認を受けた期間の保険料は10年以内であれば追納できるが、学生納付特例の承認を受けた期間の保険料は追納できない。",a:false,e:"法94条1項。学生納付特例期間・納付猶予期間はいずれも10年以内の追納が可能。",topic:"追納"},
 {id:"X6-087",s:6,q:"付加保険料は、保険料の半額免除を受けている第1号被保険者であっても納付することができる。",a:false,e:"法87条の2第1項。全額免除者のほか、一部免除者・学生納付特例・納付猶予の者、国民年金基金の加入員は付加保険料を納付できない。",topic:"付加年金"},
 {id:"X6-088",s:6,q:"付加保険料を納付する者となる申出をした場合、その申出をした日の属する月の翌月から付加保険料を納付する者となる。",a:false,e:"法87条の2第1項。申出をした日の属する月以後の各月について付加保険料を納付する者となる。",topic:"付加年金"},
 {id:"X6-089",s:6,q:"付加保険料を納付する者は、いつでも厚生労働大臣に申し出て、付加保険料を納付する者でなくなることができる。",a:true,e:"法87条の2第3項。申出をした日の属する月の前月以後の各月(納付・前納済みを除く)について納付する者でなくなる。",topic:"付加年金"},
 {id:"X6-090",s:6,q:"付加保険料を納付する者が国民年金基金の加入員となったときは、その加入員となった日に、付加保険料を納付する者でなくなる旨の申出をしたものとみなされる。",a:true,e:"法87条の2第4項。基金は付加年金相当部分を代行するため、基金加入員は付加保険料を納付できない。",topic:"付加年金"},
 {id:"X6-091",s:6,q:"付加保険料の額は、保険料改定率により毎年度改定される。",a:false,e:"法87条の2。付加保険料は月額400円の定額で改定率による改定はない。付加年金の額も200円に月数を乗じた定額。",topic:"付加年金"},
 {id:"X6-092",s:6,q:"付加年金は、老齢基礎年金の受給権者であれば、付加保険料に係る保険料納付済期間の有無にかかわらず支給される。",a:false,e:"法43条。付加保険料に係る保険料納付済期間を有する者が老齢基礎年金の受給権を取得したときに支給される。",topic:"付加年金"},
 {id:"X6-093",s:6,q:"付加年金は、老齢基礎年金がその全額につき支給を停止されている間は、その支給を停止する。",a:true,e:"法47条。付加年金は老齢基礎年金に連動し、単独では支給されない。老齢基礎年金の受給権が消滅したときは付加年金の受給権も消滅する。",topic:"付加年金"},
 {id:"X6-094",s:6,q:"老齢基礎年金の支給繰下げの申出をした場合、付加年金も老齢基礎年金と同じ増額率で増額される。",a:true,e:"法46条・28条。付加年金は老齢基礎年金と一体で繰上げ・繰下げされ、同率で減額・増額される。",topic:"付加年金"},
 {id:"X6-095",s:6,q:"寡婦年金の額には、死亡した夫が付加保険料を納付していた場合であっても、付加年金に相当する額は加算されない。",a:true,e:"法50条。寡婦年金は夫の第1号期間に基づく老齢基礎年金額の4分の3。付加が反映されるのは死亡一時金の8,500円加算。",topic:"付加年金"},
 {id:"X6-096",s:6,q:"昭和61年4月以降に20歳以上60歳未満で海外に居住していた日本人の期間であっても、国民年金に任意加入しなかった期間は合算対象期間とならない。",a:false,e:"昭和60年改正法附則8条5項。海外在住日本人の20歳以上60歳未満の任意未加入期間は合算対象期間となる。",topic:"受給資格期間"},
 {id:"X6-097",s:6,q:"昭和61年3月以前に、厚生年金保険の被保険者の配偶者で国民年金に任意加入しなかった20歳以上60歳未満の期間は、合算対象期間となる。",a:true,e:"昭和60年改正法附則8条5項。旧法で任意加入の対象だった被用者の配偶者の未加入期間はいわゆるカラ期間。",topic:"受給資格期間"},
 {id:"X6-098",s:6,q:"平成3年3月以前の20歳以上60歳未満の学生であって、国民年金に任意加入しなかった期間は、合算対象期間となる。",a:true,e:"昭和60年改正法附則8条5項。学生が強制加入となったのは平成3年4月から。それ以前の任意未加入期間はカラ期間。",topic:"受給資格期間"},
 {id:"X6-099",s:6,q:"昭和61年4月以降の厚生年金保険の被保険者期間のうち、20歳前及び60歳以後の期間は、老齢基礎年金の年金額の計算上、保険料納付済期間として扱われる。",a:false,e:"昭和60年改正法附則8条4項・5項。20歳前・60歳以後の第2号期間は老齢基礎年金では合算対象期間。老齢厚生年金の経過的加算で補われる。",topic:"受給資格期間"},
 {id:"X6-100",s:6,q:"20歳前の第2号被保険者期間は、障害基礎年金の保険料納付要件の判定においては保険料納付済期間として扱われる。",a:true,e:"法5条1項・30条。第2号期間は保険料納付済期間。20歳前・60歳以後を合算対象期間とするのは老齢基礎年金に関する特例。",topic:"受給資格期間"},
 {id:"X6-101",s:6,q:"脱退手当金の支給を受けた厚生年金保険の被保険者期間のうち昭和36年4月以後の期間は、昭和61年4月から65歳に達する日の前日までの間に保険料納付済期間又は保険料免除期間を有する場合に、合算対象期間となる。",a:true,e:"昭和60年改正法附則8条5項。脱退手当金の計算の基礎となった期間の扱い。脱退手当金を受けた期間も一定の場合は受給資格期間の計算に活かされる。",topic:"受給資格期間"},
 {id:"X6-102",s:6,q:"老齢基礎年金の受給資格期間は、保険料納付済期間又は保険料免除期間を有する者について、合算対象期間を加えて10年以上あれば満たされる。",a:true,e:"法26条・附則9条1項。納付済期間・免除期間・合算対象期間の合計が10年以上で受給資格を満たす。",topic:"受給資格期間"},
 {id:"X6-103",s:6,q:"老齢基礎年金は、保険料納付済期間と保険料免除期間を合算した期間が10年以上ある者が60歳に達したときに支給される。",a:false,e:"法26条。支給開始は65歳。60歳から65歳までの受給は支給繰上げの請求による(附則9条の2)。",topic:"受給資格期間"},
 {id:"X6-104",s:6,q:"第3号被保険者としての被保険者期間は、老齢基礎年金の額の計算において保険料納付済期間として扱われる。",a:true,e:"法5条1項。第3号は保険料を個別に負担しないが、その期間は保険料納付済期間とされる。",topic:"受給資格期間"},
 {id:"X6-105",s:6,q:"保険料全額免除期間は、平成21年4月以降の期間であっても、老齢基礎年金の受給資格期間には算入されない。",a:false,e:"法26条・5条2項。保険料免除期間は受給資格期間に算入される。学生納付特例・納付猶予期間も同様。",topic:"受給資格期間"},
 {id:"X6-106",s:6,q:"保険料納付済期間と保険料免除期間の合計が480月を超える場合でも、保険料免除期間はすべて老齢基礎年金の額に反映される。",a:false,e:"法27条ただし書。免除期間の月数は480から納付済期間等の月数を控除した月数が限度となるため、480月を超える部分は反映されない。",topic:"老齢基礎年金"},
 {id:"X6-107",s:6,q:"60歳以後に任意加入被保険者として保険料を納付した期間は、老齢基礎年金の額の計算上、保険料納付済期間に算入される。",a:true,e:"法5条1項・附則5条・法27条。任意加入者は第1号とみなされ、その納付済期間は年金額に反映される(上限480月)。",topic:"老齢基礎年金"},
 {id:"X6-108",s:6,q:"老齢基礎年金の額の改定は、受給権者の年齢にかかわらず、名目手取り賃金変動率を基準として行われる。",a:false,e:"法27条の2・27条の3。原則として68歳到達年度前の者は名目手取り賃金変動率、以後の者は物価変動率を基準に改定する。",topic:"老齢基礎年金"},
 {id:"X6-109",s:6,q:"平成21年3月以前の保険料半額免除期間は、老齢基礎年金の額の計算上、3分の2として反映される。",a:true,e:"法27条・平成16年改正法附則。国庫負担3分の1時代は、全額免除3分の1、4分の3免除2分の1、半額免除3分の2、4分の1免除6分の5。",topic:"老齢基礎年金"},
 {id:"X6-110",s:6,q:"平成21年4月以降の保険料4分の1免除期間は、老齢基礎年金の額の計算上、6分の5として反映される。",a:false,e:"法27条。平成21年4月以降の4分の1免除期間は8分の7。6分の5は平成21年3月以前の4分の1免除期間の反映割合。",topic:"老齢基礎年金"},
 {id:"X6-111",s:6,q:"老齢基礎年金の年金額の計算の基礎となるのは、原則として20歳以上60歳未満の期間に係る保険料納付済期間及び保険料免除期間である。",a:true,e:"法27条・昭和60年改正法附則8条4項。第2号の20歳前・60歳以後は除かれる。60歳以後の任意加入の納付済期間は算入される。",topic:"老齢基礎年金"},
 {id:"X6-112",s:6,q:"老齢基礎年金の受給権は、受給権者が死亡したときに限り消滅する。",a:true,e:"法29条。老齢基礎年金の失権事由は死亡のみ。障害基礎年金・遺族基礎年金には死亡以外の失権事由がある。",topic:"老齢基礎年金"},
 {id:"X6-113",s:6,q:"老齢基礎年金は、受給権者が厚生年金保険の被保険者として就労し一定以上の賃金を得ている場合には、在職老齢年金の仕組みにより支給停止される。",a:false,e:"厚年法46条。在職老齢年金による調整の対象は老齢厚生年金のみ。老齢基礎年金は在職を理由に支給停止されない。",topic:"老齢基礎年金"},
 {id:"X6-114",s:6,q:"老齢基礎年金の受給権者が日本国内に住所を有しなくなっても、そのことを理由に老齢基礎年金の支給が停止されることはない。",a:true,e:"法36条の2参照。国外居住による支給停止は20歳前傷病による障害基礎年金などの規定であり、老齢基礎年金にはない。",topic:"老齢基礎年金"},
 {id:"X6-115",s:6,q:"老齢基礎年金の支給繰上げの請求をした場合、請求をした日の属する月の翌月分から老齢基礎年金が支給される。",a:true,e:"法附則9条の2第3項・法18条1項。繰上げ請求日に受給権が発生し、その翌月分から支給される。",topic:"繰上げ・繰下げ"},
 {id:"X6-116",s:6,q:"老齢基礎年金の支給繰上げの請求をした者は、65歳に達するまでの間であれば、その請求を取り消して65歳から本来の額で受給し直すことができる。",a:false,e:"法附則9条の2。繰上げ請求後にこれを取り消すことはできず、減額された額が65歳以後も生涯続く。",topic:"繰上げ・繰下げ"},
 {id:"X6-117",s:6,q:"任意加入被保険者である間は、老齢基礎年金の支給繰上げの請求をすることができない。",a:true,e:"法附則9条の2第1項。繰上げ請求は任意加入被保険者でない者に限られる。任意加入を続けたまま減額された年金を受けることはできない。",topic:"繰上げ・繰下げ"},
 {id:"X6-118",s:6,q:"老齢厚生年金の支給繰上げの請求をすることができる者が老齢基礎年金の繰上げを請求するときは、老齢厚生年金の繰上げの請求と同時に行わなければならない。",a:true,e:"法附則9条の2第2項。老齢基礎年金と老齢厚生年金の繰上げは同時に請求する。基礎年金のみ・厚生年金のみの繰上げはできない。",topic:"繰上げ・繰下げ"},
 {id:"X6-119",s:6,q:"老齢基礎年金の繰上げ支給を受けている者であっても、65歳前に障害の程度が増進した場合には、事後重症による障害基礎年金を請求することができる。",a:false,e:"法附則9条の2の3。繰上げ受給者は65歳に達したものとみなされ、事後重症・基準障害による障害基礎年金を請求できない。",topic:"繰上げ・繰下げ"},
 {id:"X6-120",s:6,q:"寡婦年金の受給権者である妻が老齢基礎年金の繰上げ支給の受給権を取得したときは、寡婦年金の受給権は消滅する。",a:true,e:"法附則9条の2。繰上げ受給権の取得は寡婦年金の失権事由。寡婦年金との二重受給はできない。",topic:"繰上げ・繰下げ"},
 {id:"X6-121",s:6,q:"70歳に達した日後に老齢基礎年金を請求し、かつ繰下げの申出をしない場合には、原則として、請求をした日の5年前の日に繰下げの申出があったものとみなされる。",a:true,e:"法28条5項。令和5年4月施行の特例的な繰下げみなし増額。請求時に80歳以上である場合などは対象外。",topic:"繰上げ・繰下げ"},
 {id:"X6-122",s:6,q:"老齢基礎年金の支給繰下げの申出をした場合、増額された老齢基礎年金は、申出をした日の属する月から支給される。",a:false,e:"法28条3項。繰下げの申出をした者の老齢基礎年金は、申出のあった日の属する月の翌月から支給される。",topic:"繰上げ・繰下げ"},
 {id:"X6-123",s:6,q:"老齢基礎年金の繰下げによる増額率は、受給権取得月から繰下げ申出月の前月までの月数(上限120月)に1000分の7を乗じて得た率である。",a:true,e:"法28条4項・令4条の5。0.7%×最大120月=84%。昭和27年4月2日以後生まれが75歳まで繰下げ可能。",topic:"繰上げ・繰下げ"},
 {id:"X6-124",s:6,q:"66歳到達日後に遺族厚生年金の受給権を取得した者が、その後に老齢基礎年金の支給繰下げの申出をしたときは、遺族厚生年金の受給権を取得した日に繰下げの申出があったものとみなされる。",a:true,e:"法28条2項。66歳到達日後に他の年金たる給付の受給権者となった者が繰下げの申出をしたときは、その受給権者となった日に申出があったものとみなされ、増額率はその時点で固定される。",topic:"繰上げ・繰下げ"},
 {id:"X6-125",s:6,q:"老齢基礎年金の繰下げ待機中の者は、繰下げの申出をせずに65歳にさかのぼって本来の額で受給することはできない。",a:false,e:"法28条・102条。繰下げの申出をせず本来額で遡って請求することもできる。ただし支分権の時効(5年)にかかる部分は受給できない。",topic:"繰上げ・繰下げ"},
 {id:"X6-126",s:6,q:"振替加算は、配偶者が受ける老齢厚生年金(被保険者期間20年以上等)の加給年金額の対象となっていた者が65歳に達したときに、その者の老齢基礎年金に加算される。",a:true,e:"昭和60年改正法附則14条。65歳到達日の前日において配偶者により生計を維持されていたことが要件。",topic:"振替加算"},
 {id:"X6-127",s:6,q:"振替加算は、老齢基礎年金の受給権者本人が被保険者期間20年以上の老齢厚生年金を受けることができる場合でも加算される。",a:false,e:"昭和60年改正法附則14条1項ただし書。本人が厚年期間20年以上の老齢厚生年金等を受けることができるときは加算されない。",topic:"振替加算"},
 {id:"X6-128",s:6,q:"振替加算の額は、受給権者の生年月日に応じて定められた率を乗じて得た額であり、生年月日が遅い者ほど少なくなる。",a:true,e:"昭和60年改正法附則14条・政令。大正15年4月2日〜昭和2年4月1日生まれは1.000、昭和36年4月2日〜昭和41年4月1日生まれは0.067。",topic:"振替加算"},
 {id:"X6-129",s:6,q:"合算対象期間と学生納付特例期間のみで受給資格期間を満たす者であっても、振替加算の要件を満たせば、振替加算に相当する額の老齢基礎年金が支給される。",a:true,e:"昭和60年改正法附則15条。納付済期間・免除期間(学生納付特例期間等を除く)がなくても、振替加算相当額の老齢基礎年金が支給される。",topic:"振替加算"},
 {id:"X6-130",s:6,q:"障害認定日は、原則として初診日から起算して1年6月を経過した日であるが、その期間内に傷病が治った場合(症状が固定した場合を含む)はその治った日となる。",a:true,e:"法30条1項。障害認定日の定義。認定日に障害等級に該当すればその翌月から支給される。本来請求が遅れても時効にかからない分は遡って支給される。",topic:"障害基礎年金"},
 {id:"X6-131",s:6,q:"障害基礎年金の支給要件である初診日とは、その傷病について初めて障害の状態にあると認定された日をいう。",a:false,e:"法30条1項。初診日は、その傷病について初めて医師又は歯科医師の診療を受けた日をいう。",topic:"障害基礎年金"},
 {id:"X6-132",s:6,q:"初診日において被保険者でなくても、被保険者であった者で日本国内に住所を有し60歳以上65歳未満である者は、障害基礎年金の支給対象となりうる。",a:true,e:"法30条1項2号。60歳以上65歳未満の非被保険者は国内住所が要件。初診日に被保険者であった場合は住所要件なし。",topic:"障害基礎年金"},
 {id:"X6-133",s:6,q:"初診日に60歳以上65歳未満で日本国内に住所を有しない者(被保険者であった者)であっても、保険料納付要件を満たせば障害基礎年金を受けることができる。",a:false,e:"法30条1項2号。被保険者でない60歳以上65歳未満の者については、日本国内に住所を有することが要件。",topic:"障害基礎年金"},
 {id:"X6-134",s:6,q:"初診日に海外に居住していた任意加入被保険者についても、保険料納付要件等を満たせば障害基礎年金が支給されうる。",a:true,e:"法30条1項1号。初診日に「被保険者」であれば国内住所の有無は問われない。国内住所要件があるのは60歳以上65歳未満の非被保険者のみ。",topic:"障害基礎年金"},
 {id:"X6-135",s:6,q:"障害基礎年金の保険料納付要件(3分の2要件)の判定においては、合算対象期間も保険料納付済期間とあわせて算入される。",a:false,e:"法30条1項ただし書。判定は被保険者期間のうち保険料納付済期間と保険料免除期間で行い、合算対象期間は算入されない。",topic:"障害基礎年金"},
 {id:"X6-136",s:6,q:"初診日において20歳未満であった者(被保険者でなかった者)の障害基礎年金については、保険料納付要件は問われない。",a:true,e:"法30条の4。20歳前傷病による障害基礎年金は納付要件を問わない代わりに、本人の所得による支給制限等がある。",topic:"障害基礎年金"},
 {id:"X6-137",s:6,q:"初診日に被保険者であった者が障害認定日に障害等級に該当するときは、障害認定日の属する月の翌月から障害基礎年金が支給される。",a:true,e:"法30条・18条1項。請求が遅れても、支分権の時効(5年)にかからない範囲で遡って支給される。",topic:"障害基礎年金"},
 {id:"X6-138",s:6,q:"事後重症による障害基礎年金の受給権を取得した場合、障害認定日の属する月の翌月まで遡って支給される。",a:false,e:"法30条の2・18条1項。事後重症は請求によって受給権が発生し、請求月の翌月から支給される。遡及しない。",topic:"障害基礎年金"},
 {id:"X6-139",s:6,q:"基準障害による障害基礎年金の保険料納付要件は、基準傷病(後発の傷病)に係る初診日の前日において判定する。",a:true,e:"法30条の3。基準傷病の初診日で納付要件を判定する。前発の傷病の納付要件は問わない。",topic:"障害基礎年金"},
 {id:"X6-140",s:6,q:"障害基礎年金の受給権者が、受給権を取得した日の翌日以後に生計を維持する子を有するに至った場合には、その子について加算は行われない。",a:false,e:"法33条の2第2項。平成23年4月以降、受給権取得後に生計を維持する子を有するに至った場合も、その翌月から加算される。",topic:"障害基礎年金"},
 {id:"X6-141",s:6,q:"障害基礎年金の子の加算の対象となっている子が婚姻をしたときは、その翌月から年金額が減額改定される。",a:true,e:"法33条の2第3項。子の死亡、婚姻、受給権者の配偶者以外の者の養子となったこと、18歳年度末の終了等で減額される。",topic:"障害基礎年金"},
 {id:"X6-142",s:6,q:"障害基礎年金の子の加算の対象となっている子が受給権者の配偶者の養子となったときは、加算額が減額される。",a:false,e:"法33条の2第3項3号。減額事由は受給権者の配偶者「以外」の者の養子となったとき。配偶者の養子となっても加算は続く。",topic:"障害基礎年金"},
 {id:"X6-143",s:6,q:"障害基礎年金には配偶者に係る加算はなく、配偶者に係る加給年金額は障害厚生年金(1級・2級)に加算される。",a:true,e:"法33条の2・厚年法50条の2。障害基礎年金に加算されるのは子の加算のみ。子の加算は受給権取得後に生まれた子も対象。",topic:"障害基礎年金"},
 {id:"X6-144",s:6,q:"障害基礎年金は、その受給権者が当該傷病について労働基準法の規定による障害補償を受ける権利を取得したときは、6年間その支給を停止する。",a:true,e:"法36条1項。労基法の障害補償との調整。労災保険の障害補償年金との調整は労災側の減額で行われる。",topic:"障害基礎年金"},
 {id:"X6-145",s:6,q:"障害基礎年金(20歳前傷病によるものを除く)の受給権者が同一の傷病により労災保険の障害補償年金を受けるときは、障害基礎年金が6年間支給停止される。",a:false,e:"法36条1項。6年間の停止は労基法の障害補償の場合。労災年金との併給は労災年金側が減額調整され、障害基礎年金は全額支給される。",topic:"障害基礎年金"},
 {id:"X6-146",s:6,q:"障害基礎年金は、受給権者が障害等級に該当する程度の障害の状態に該当しなくなったときは、その該当しない間、その支給を停止する。",a:true,e:"法36条2項。再び2級以上に該当すれば停止が解除される。一定の場合は失権(法35条)。",topic:"障害基礎年金"},
 {id:"X6-147",s:6,q:"20歳前傷病による障害基礎年金は、受給権者が刑事施設等に拘禁されている場合など一定の場合には、その支給が停止される。",a:true,e:"法36条の2第1項。刑事施設・労役場等への拘禁、少年院等への収容、国内住所の喪失などで支給停止となる。",topic:"障害基礎年金"},
 {id:"X6-148",s:6,q:"20歳前傷病による障害基礎年金は、受給権者が日本国内に住所を有しなくなっても、その支給は停止されない。",a:false,e:"法36条の2第1項。20歳前傷病の障害基礎年金は、日本国内に住所を有しないときは支給停止となる。",topic:"障害基礎年金"},
 {id:"X6-149",s:6,q:"20歳前傷病による障害基礎年金の所得による支給停止は、受給権者本人の前年の所得により判定される。",a:true,e:"法36条の3。扶養親族等の数に応じた基準を超えると2分の1又は全額が停止される。",topic:"障害基礎年金"},
 {id:"X6-150",s:6,q:"厚生労働大臣は、障害基礎年金の受給権者の障害の程度を診査し、その程度が従前の障害等級以外の等級に該当すると認めるときは、職権で年金額を改定することができる。",a:true,e:"法34条1項。職権改定。受給権者による額の改定請求は同条2項。いずれも2級→1級などの等級変更に対応する仕組み。",topic:"障害基礎年金"},
 {id:"X6-151",s:6,q:"障害基礎年金の受給権者に障害等級に該当しない程度の障害(その他障害)が新たに生じ、前後の障害を併合した程度が従前より増進したときは、65歳に達する日の前日までの間に限り額の改定請求ができる。",a:true,e:"法34条4項。その他障害との併合による改定請求は65歳到達日の前日まで。65歳以後は、その他障害との併合による改定請求はできない。",topic:"障害基礎年金"},
 {id:"X6-152",s:6,q:"障害基礎年金の受給権は、受給権者が65歳に達したときに消滅する。",a:false,e:"法35条。65歳到達そのものは失権事由ではない。3級不該当のまま65歳到達と3年経過のいずれか遅い方が到来したときなどに失権。",topic:"障害基礎年金"},
 {id:"X6-153",s:6,q:"障害等級3級にも該当しない状態で65歳に達した障害基礎年金の受給権者であっても、3級不該当となった日から3年を経過していないときは、受給権は消滅しない。",a:true,e:"法35条。3級不該当のまま、65歳到達と3年経過のいずれか遅いほうが到来した時に失権する。",topic:"障害基礎年金"},
 {id:"X6-154",s:6,q:"障害基礎年金の受給権者が老齢基礎年金の受給権を取得したときは、障害基礎年金の受給権は消滅する。",a:false,e:"法35条・20条。受給権は消滅せず、併給調整(1人1年金)によりいずれか一方を選択して受給する。",topic:"障害基礎年金"},
 {id:"X6-155",s:6,q:"故意に障害又はその直接の原因となった事故を生じさせた者の当該障害については、障害基礎年金の一部を支給しないことができるにとどまる。",a:false,e:"法69条。故意による障害には障害基礎年金を支給しない(絶対的不支給)。重大な過失等による場合(法70条)は全部又は一部を行わないことができる。",topic:"障害基礎年金"},
 {id:"X6-156",s:6,q:"故意の犯罪行為若しくは重大な過失により障害を生じさせた者の当該障害については、障害基礎年金の全部又は一部を行わないことができる。",a:true,e:"法70条。相対的な給付制限。故意による場合(法69条)は必ず不支給。故意の犯罪行為・重大な過失は裁量による制限である点が69条との違い。",topic:"障害基礎年金"},
 {id:"X6-157",s:6,q:"障害基礎年金の受給権者が、正当な理由なく厚生労働大臣の命ずる受診に応じないときは、年金給付の全部又は一部の支給を停止することができる。",a:true,e:"法72条。障害の状態の診査に応じない場合等の支給停止。障害の程度の確認ができないため、支給を停止できるとされている。",topic:"障害基礎年金"},
 {id:"X6-158",s:6,q:"被保険者であった者で日本国内に住所を有する60歳以上65歳未満の者が死亡したことによる遺族基礎年金については、保険料納付要件が問われる。",a:true,e:"法37条ただし書。被保険者及び60歳以上65歳未満の者の死亡(短期要件)は納付要件あり。老齢基礎年金の受給権者等(長期要件)は不要。",topic:"遺族基礎年金"},
 {id:"X6-159",s:6,q:"老齢基礎年金の受給権者が死亡した場合には、その者の保険料納付済期間等の長短にかかわらず、遺族基礎年金の支給要件を満たす。",a:false,e:"法37条3号。受給権者・受給資格者の死亡については、納付済期間・免除期間・合算対象期間の合計が25年以上ある者に限られる。",topic:"遺族基礎年金"},
 {id:"X6-160",s:6,q:"老齢基礎年金の受給資格期間(保険料納付済期間等の合計が25年以上)を満たした者が、受給権を取得する前に死亡した場合も、遺族基礎年金の支給要件を満たす。",a:true,e:"法37条4号。いわゆる長期要件であり、保険料納付要件は問われない。老齢基礎年金の受給資格期間10年とは異なる点に注意。",topic:"遺族基礎年金"},
 {id:"X6-161",s:6,q:"日本国内に住所を有しない60歳以上65歳未満の被保険者であった者が死亡した場合も、保険料納付要件を満たせば遺族基礎年金が支給される。",a:false,e:"法37条2号。被保険者でない60歳以上65歳未満の者については日本国内に住所を有することが要件。",topic:"遺族基礎年金"},
 {id:"X6-162",s:6,q:"遺族基礎年金を受けることができる配偶者は、被保険者等の死亡の当時その者によって生計を維持し、かつ、遺族の範囲に該当する子と生計を同じくしていることが要件となる。",a:true,e:"法37条の2第1項1号。子のない配偶者は遺族基礎年金を受けられない。子のない配偶者の救済は寡婦年金・死亡一時金が担う。",topic:"遺族基礎年金"},
 {id:"X6-163",s:6,q:"遺族基礎年金を受けることができる配偶者は妻に限られ、夫は子と生計を同じくしている場合でも受けることができない。",a:false,e:"法37条の2。平成26年4月から子のある夫も対象となった(父子家庭への支給拡大)。",topic:"遺族基礎年金"},
 {id:"X6-164",s:6,q:"被保険者等の死亡の当時胎児であった子が生まれたときは、将来に向かって、その子は死亡の当時その者によって生計を維持していたものとみなされる。",a:true,e:"法37条の2第2項。配偶者も死亡の当時その子と生計を同じくしていたものとみなされる。",topic:"遺族基礎年金"},
 {id:"X6-165",s:6,q:"被保険者等の死亡の当時胎児であった子が出生したときは、被保険者等が死亡した日の属する月の翌月まで遡って遺族基礎年金が支給される。",a:false,e:"法37条の2第2項。出生により「将来に向かって」生計維持をみなすため、遡及はされず出生月の翌月から支給される。",topic:"遺族基礎年金"},
 {id:"X6-166",s:6,q:"遺族基礎年金の遺族となる子は、18歳に達する日以後の最初の3月31日までの間にあるか、20歳未満で障害等級1級又は2級の障害の状態にあり、かつ、現に婚姻をしていないことが要件である。",a:true,e:"法37条の2第1項2号。子の年齢・障害・婚姻に関する要件。18歳到達年度末までの子、又は20歳未満で障害等級1・2級の子で未婚の者。",topic:"遺族基礎年金"},
 {id:"X6-167",s:6,q:"死亡した者の配偶者の連れ子であって、死亡した者と養子縁組をしていない者も、遺族基礎年金の遺族となる子に含まれる。",a:false,e:"法37条の2。子は死亡した者の子(実子・養子)に限られる。養子縁組をしていない配偶者の連れ子は含まれない。",topic:"遺族基礎年金"},
 {id:"X6-168",s:6,q:"配偶者に支給する遺族基礎年金の額は、基本額に、配偶者と生計を同じくする遺族の範囲に該当する子の数に応じた加算額を加算した額である。",a:true,e:"法39条1項。子の加算は2人目までは同額、3人目以降は減額された額。",topic:"遺族基礎年金"},
 {id:"X6-169",s:6,q:"子が遺族基礎年金の受給権を取得し、子が2人以上いるときは、基本額をその子の数で除した額がそれぞれに支給され、子の加算額は一切加算されない。",a:false,e:"法39条の2。子のみが受給する場合、基本額に2人目以降の子の加算額を加えた額を子の数で除して各子に支給する。",topic:"遺族基礎年金"},
 {id:"X6-170",s:6,q:"配偶者の遺族基礎年金の受給権は、加算の対象となっている子のすべてが減額事由に該当したときに消滅する。",a:true,e:"法40条2項。子のすべてが18歳年度末の終了や婚姻などで加算対象から外れると、配偶者は失権する。",topic:"遺族基礎年金"},
 {id:"X6-171",s:6,q:"遺族基礎年金の受給権者である配偶者が、直系血族の養子となったときは、その受給権は消滅する。",a:false,e:"法40条1項3号。直系血族又は直系姻族の養子となったときは失権しない。それ以外の者の養子となったときに失権する。",topic:"遺族基礎年金"},
 {id:"X6-172",s:6,q:"遺族基礎年金の受給権者が婚姻(届出をしていない事実上の婚姻関係を含む)をしたときは、その受給権は消滅する。",a:true,e:"法40条1項2号。婚姻は配偶者・子に共通の失権事由。届出をしていない事実上の婚姻関係も含まれる。",topic:"遺族基礎年金"},
 {id:"X6-173",s:6,q:"子の遺族基礎年金の受給権は、離縁によって、死亡した被保険者又は被保険者であった者の子でなくなったときに消滅する。",a:true,e:"法40条3項1号。子固有の失権事由として離縁がある。養子縁組が解消され、死亡者の子でなくなれば失権する。",topic:"遺族基礎年金"},
 {id:"X6-174",s:6,q:"障害等級2級の障害の状態にある子の遺族基礎年金の受給権は、その子が25歳に達したときに消滅する。",a:false,e:"法40条3項。障害の状態にある子は20歳に達したときに失権する。障害の状態にない子は18歳到達年度の末日が終了したときに失権する。",topic:"遺族基礎年金"},
 {id:"X6-175",s:6,q:"遺族基礎年金は、被保険者等の死亡について労働基準法の規定による遺族補償が行われるべきものであるときは、死亡日から6年間、その支給を停止する。",a:true,e:"法41条1項。障害基礎年金における障害補償との調整と同じ構造。6年間の停止後は支給が再開される。",topic:"遺族基礎年金"},
 {id:"X6-176",s:6,q:"配偶者に対する遺族基礎年金は、その配偶者の所在が1年以上明らかでないときは、厚生労働大臣の職権によりその支給が停止される。",a:false,e:"法41条の2第1項。遺族基礎年金の受給権を有する子の申請によって、所在不明となった時にさかのぼって支給を停止する。",topic:"遺族基礎年金"},
 {id:"X6-177",s:6,q:"遺族基礎年金の受給権を有する子が2人以上ある場合に、1人の所在が1年以上明らかでないときは他の子の申請により支給を停止できるが、所在が明らかになってもその停止を解除することはできない。",a:false,e:"法42条。停止された子は、いつでも支給停止の解除を申請することができる(同2項)。所在不明だった子自身の申請により停止が解除される。",topic:"遺族基礎年金"},
 {id:"X6-178",s:6,q:"失踪の宣告を受けた者の死亡に係る遺族基礎年金の生計維持要件は、行方不明となった当時の状況により判断される。",a:true,e:"法18条の3。「死亡の当時」は「行方不明となった当時」と読み替えられる。身分関係・年齢・障害の状態は読替えの対象外。",topic:"遺族基礎年金"},
 {id:"X6-179",s:6,q:"船舶が沈没し、その船舶に乗っていた者の生死が3か月間わからない場合には、船舶が沈没した日から3か月を経過した日にその者が死亡したものと推定される。",a:false,e:"法18条の2。船舶が沈没した日(行方不明となった日)に死亡したものと推定する。航空機の墜落等の場合も同様。死亡推定日を基準に遺族を判定する。",topic:"遺族基礎年金"},
 {id:"X6-180",s:6,q:"被保険者を故意に死亡させた者であっても、その者が遺族の範囲に該当すれば遺族基礎年金が支給される。",a:false,e:"法71条1項。被保険者等を故意に死亡させた者には、遺族基礎年金・寡婦年金・死亡一時金を支給しない。",topic:"遺族基礎年金"},
 {id:"X6-181",s:6,q:"遺族基礎年金の受給権者である妻が死亡し未支給の年金がある場合、その額の加算の対象となっていた夫の子は、妻と養子縁組をしていなくても未支給年金の請求について妻の子とみなされる。",a:true,e:"法19条2項。遺族基礎年金の支給要件・加算の対象となっていた子は、未支給年金の請求について死亡者の子とみなす。",topic:"遺族基礎年金"},
 {id:"X6-182",s:6,q:"寡婦年金は、死亡した夫の死亡日の前日において、死亡日の属する月の前月までの第1号被保険者としての被保険者期間に係る保険料納付済期間と保険料免除期間の合計が10年以上あることが要件である。",a:true,e:"法49条1項。第1号としての期間で判定する。第2号・第3号期間は算入しない。",topic:"寡婦年金"},
 {id:"X6-183",s:6,q:"寡婦年金は、夫との婚姻関係(事実上の婚姻関係を含む)が5年以上継続していた妻に支給される。",a:false,e:"法49条1項。婚姻関係が10年以上継続した65歳未満の妻に支給される。",topic:"寡婦年金"},
 {id:"X6-184",s:6,q:"死亡した夫が障害基礎年金の支給を受けたことがあるときは、寡婦年金は支給されない。",a:true,e:"法49条1項ただし書。夫が障害基礎年金の受給権者であったことがあるとき、又は老齢基礎年金の支給を受けていたときは、寡婦年金は支給されない。",topic:"寡婦年金"},
 {id:"X6-185",s:6,q:"寡婦年金の額は、死亡した夫の第1号被保険者期間に係る老齢基礎年金の額の2分の1に相当する額である。",a:false,e:"法50条。夫の第1号被保険者期間に基づく老齢基礎年金額の4分の3に相当する額。",topic:"寡婦年金"},
 {id:"X6-186",s:6,q:"60歳未満で夫を亡くした妻に対する寡婦年金は、妻が60歳に達した日の属する月の翌月から支給される。",a:true,e:"法49条3項・18条。60歳から65歳に達するまでの有期年金。60歳以上で夫が死亡したときは死亡日の翌月から支給される。",topic:"寡婦年金"},
 {id:"X6-187",s:6,q:"寡婦年金の受給権者が再婚したときは、寡婦年金の受給権は消滅する。",a:true,e:"法51条。65歳到達、死亡、婚姻、直系血族・直系姻族以外の者の養子となったときなどに失権する。",topic:"寡婦年金"},
 {id:"X6-188",s:6,q:"寡婦年金は、夫の死亡当時夫によって生計を維持されていなかった妻であっても、婚姻期間の要件を満たせば支給される。",a:false,e:"法49条1項。夫の死亡当時夫によって生計を維持されていたことが要件。遺族基礎年金と同様、生計維持の認定が必要。",topic:"寡婦年金"},
 {id:"X6-189",s:6,q:"死亡一時金の支給要件である36月の計算において、保険料半額免除期間の月数はその全月数が算入される。",a:false,e:"法52条の2。4分の1免除月数の4分の3、半額免除月数の2分の1、4分の3免除月数の4分の1を算入。全額免除期間は算入しない。",topic:"死亡一時金"},
 {id:"X6-190",s:6,q:"死亡一時金を受けることができる遺族の順位は、配偶者、子、父母、孫、祖父母、兄弟姉妹の順であり、いずれも死亡の当時その者と生計を同じくしていたことが要件である。",a:true,e:"法52条の3。遺族基礎年金と異なり、子のない配偶者や父母なども対象。遺族基礎年金を受けられる者がいるときは原則として支給されない。",topic:"死亡一時金"},
 {id:"X6-191",s:6,q:"死亡一時金の遺族となる兄弟姉妹は、死亡の当時その者によって生計を維持されていたことが要件である。",a:false,e:"法52条の3。要件は死亡の当時その者と「生計を同じくしていた」こと。生計維持までは求められない。",topic:"死亡一時金"},
 {id:"X6-192",s:6,q:"死亡した者の死亡により遺族基礎年金を受けることができる者があるときは、原則として死亡一時金は支給されない。",a:true,e:"法52条の2第2項。ただし死亡日の属する月に遺族基礎年金の受給権が消滅したときは支給される。",topic:"死亡一時金"},
 {id:"X6-193",s:6,q:"死亡により遺族基礎年金の受給権を取得した子が、生計を同じくするその子の母があることにより遺族基礎年金の支給を停止されるときは、死亡一時金が支給される。",a:true,e:"法52条の2。子の遺族基礎年金が父又は母との生計同一により停止される場合は、死亡一時金の支給制限の例外となる。",topic:"死亡一時金"},
 {id:"X6-194",s:6,q:"付加保険料に係る保険料納付済期間が3年以上ある者の死亡による死亡一時金には、8,500円が加算される。",a:true,e:"法52条の4第2項。付加保険料納付済期間3年以上で定額8,500円が加算される。",topic:"死亡一時金"},
 {id:"X6-195",s:6,q:"死亡一時金の額は、死亡した者の保険料納付済期間等の月数にかかわらず一律の額である。",a:false,e:"法52条の4第1項。保険料納付済期間等の月数に応じて6段階の額が定められている。額は12万円から32万円まで、月数が多いほど高くなる。",topic:"死亡一時金"},
 {id:"X6-196",s:6,q:"脱退一時金は、日本国内に住所を有する間は請求することができない。",a:true,e:"法附則9条の3の2。日本国内に住所を有する者は請求できない。出国後に請求する。",topic:"脱退一時金"},
 {id:"X6-197",s:6,q:"脱退一時金は、最後に被保険者の資格を喪失した日から5年以内であれば請求することができる。",a:false,e:"法附則9条の3の2。資格喪失日(その日に国内に住所があるときは国内に住所を有しなくなった日)から2年以内に請求する。",topic:"脱退一時金"},
 {id:"X6-198",s:6,q:"老齢基礎年金の受給資格期間を満たしている日本国籍を有しない者は、脱退一時金を請求することができない。",a:true,e:"法附則9条の3の2。受給資格期間を満たしている者は将来老齢基礎年金を受けられるため対象外。",topic:"脱退一時金"},
 {id:"X6-199",s:6,q:"脱退一時金の支給を受けた場合でも、その計算の基礎となった期間は、老齢基礎年金の受給資格期間の計算に算入される。",a:false,e:"法附則9条の3の2。支給を受けたときは、計算の基礎となった期間は被保険者でなかったものとみなされる。",topic:"脱退一時金"},
 {id:"X6-200",s:6,q:"脱退一時金に関する処分に不服がある者は、社会保険審査官に審査請求をすることができる。",a:false,e:"法附則9条の3の2。脱退一時金に関する処分は社会保険審査会に審査請求をする(一審制)。",topic:"脱退一時金"},
 {id:"X6-201",s:6,q:"老齢基礎年金の受給権者が65歳以上であって遺族厚生年金の受給権を有するときは、老齢基礎年金と遺族厚生年金を併給することができる。",a:true,e:"法20条・附則9条の2の4。65歳以後は老齢基礎年金と遺族厚生年金の併給が可能。",topic:"併給調整"},
 {id:"X6-202",s:6,q:"遺族基礎年金と老齢厚生年金は、受給権者が65歳以上であれば併給することができる。",a:false,e:"法20条。遺族基礎年金と老齢厚生年金は併給されない。65歳以後の併給特例は老齢基礎+遺族厚生、障害基礎+老齢厚生・遺族厚生などに限られる。",topic:"併給調整"},
 {id:"X6-203",s:6,q:"65歳以上の者は、老齢基礎年金と遺族基礎年金を併給することができる。",a:false,e:"法20条。老齢基礎年金と遺族基礎年金は支給事由が異なるため併給されず、いずれか一方を選択する。",topic:"併給調整"},
 {id:"X6-204",s:6,q:"付加年金は老齢基礎年金と併給され、付加年金が単独で支給されることはない。",a:true,e:"法43条・47条。付加年金は老齢基礎年金に上乗せして支給される。",topic:"併給調整"},
 {id:"X6-205",s:6,q:"併給調整により支給を停止された年金給付の受給権者は、支給停止の解除を申請することができ、その場合は他方の年金給付の支給が停止される。",a:true,e:"法20条2項・3項。いわゆる選択替え。将来に向かって行われる。選択替えは申請のあった月の翌月から効力を生じる。",topic:"併給調整"},
 {id:"X6-206",s:6,q:"遺族基礎年金の受給権者が障害基礎年金の受給権を取得したときは、いずれか一方を選択して受給する。",a:true,e:"法20条1項。1人1年金の原則により、支給事由の異なる基礎年金同士は選択となる。同じ支給事由の老齢基礎年金と付加年金は併給される。",topic:"併給調整"},
 {id:"X6-207",s:6,q:"受給権者の申出による年金給付の支給停止は、一度申出をしたときは撤回することができない。",a:false,e:"法20条の2。申出はいつでも将来に向かって撤回することができる。",topic:"併給調整"},
 {id:"X6-208",s:6,q:"年金給付を受ける権利は、その権利を有する者の請求に基づいて、厚生労働大臣が裁定する。",a:true,e:"法16条。裁定は受給権を確認する行為。裁定を受けなければ年金は支払われない。",topic:"通則"},
 {id:"X6-209",s:6,q:"年金給付の支給を停止すべき事由が生じたときは、その事由が生じた日の属する月から、その事由が消滅した日の属する月の前月まで支給を停止する。",a:false,e:"法18条2項。事由が生じた日の属する月の翌月から、事由が消滅した日の属する月までの分の支給を停止する。",topic:"通則"},
 {id:"X6-210",s:6,q:"障害基礎年金の支給を停止して老齢基礎年金を支給すべき場合に、支給停止すべき月以降の分として障害基礎年金が支払われたときは、その支払われた障害基礎年金を老齢基礎年金の内払とみなすことはできない。",a:false,e:"法21条1項。支払われた障害基礎年金は、老齢基礎年金の内払とみなす。過払いを返還させずに調整するための規定。",topic:"通則"},
 {id:"X6-211",s:6,q:"受給権者の死亡により受給権が消滅したにもかかわらず死亡日の属する月の翌月以降の分として年金が過誤払された場合、返還すべき者が受ける遺族基礎年金等があれば、その支払金の金額に充当することができる。",a:true,e:"法21条の2。過誤払による返還金債権への充当。本人が死亡している場合の過払いを遺族の年金から回収する仕組み。",topic:"通則"},
 {id:"X6-212",s:6,q:"給付事由が第三者の行為によって生じた場合に政府が給付をしたときは、その給付の価額の限度で、受給権者が第三者に対して有する損害賠償請求権を取得する。",a:true,e:"法22条1項。第三者行為災害の求償。交通事故など第三者の加害行為による障害・死亡が典型。",topic:"通則"},
 {id:"X6-213",s:6,q:"給付事由が第三者の行為によって生じた場合に、受給権者が第三者から同一の事由について損害賠償を受けたときであっても、政府は給付を全額行わなければならない。",a:false,e:"法22条2項。政府は、その価額の限度で給付を行う責を免れる。受給権者が先に損害賠償を受けたときの調整規定。",topic:"通則"},
 {id:"X6-214",s:6,q:"偽りその他不正の手段により給付を受けた者があるときは、厚生労働大臣は、受給額に相当する金額の全部又は一部をその者から徴収することができる。",a:true,e:"法23条。不正利得の徴収。不正受給には罰則の適用もありうる。",topic:"通則"},
 {id:"X6-215",s:6,q:"給付を受ける権利は、国税滞納処分による場合であっても、例外なく差し押さえることができない。",a:false,e:"法24条ただし書。老齢基礎年金又は付加年金を受ける権利は、国税滞納処分(その例による処分を含む)により差し押さえることができる。",topic:"通則"},
 {id:"X6-216",s:6,q:"受給権者が正当な理由なく厚生労働大臣への届出や書類の提出をしないときであっても、厚生労働大臣は年金給付の支払を一時差し止めることはできない。",a:false,e:"法73条。正当な理由なく届出をせず又は書類等を提出しないときは、支払を一時差し止めることができる。",topic:"通則"},
 {id:"X6-217",s:6,q:"年金給付を受ける権利の時効は、当該年金給付がその全額につき支給を停止されている間は進行しない。",a:true,e:"法102条2項。全額支給停止中は時効が進行しない。停止が解除されると、その時から時効が進行する。",topic:"通則"},
 {id:"X6-218",s:6,q:"国民年金法に基づく給付の種類は、老齢基礎年金、障害基礎年金、遺族基礎年金、付加年金、寡婦年金及び死亡一時金である。",a:true,e:"法15条。脱退一時金は附則に規定された給付。給付の種類は6種類。脱退一時金を含めない点に注意。",topic:"通則"},
 {id:"X6-219",s:6,q:"国民年金事業は、日本年金機構が管掌する。",a:false,e:"法3条1項。国民年金事業は政府が管掌する。日本年金機構は厚生労働大臣から委任・委託を受けて事務を行う(法109条の4)。",topic:"通則"},
 {id:"X6-220",s:6,q:"国民年金事業の事務の一部は、政令の定めるところにより、市町村長(特別区の区長を含む)が行うこととすることができる。",a:true,e:"法3条3項。第1号被保険者の届出の受理などを市町村が法定受託事務として行う。",topic:"通則"},
 {id:"X6-221",s:6,q:"年金額は、国民の生活水準その他の諸事情に著しい変動が生じた場合には、変動後の諸事情に応ずるため、速やかに改定の措置が講ぜられなければならない。",a:true,e:"法4条。年金額の改定に関する政府の責務。改定率による毎年度の自動改定とは別の、政府の措置義務。",topic:"通則"},
 {id:"X6-222",s:6,q:"年金たる給付の額の算定に用いる改定率は、国会の議決を経て5年ごとに改定される。",a:false,e:"法27条の2・27条の3。改定率は毎年度、名目手取り賃金変動率や物価変動率を基準として改定される。",topic:"通則"},
 {id:"X6-223",s:6,q:"国民年金は保険料の拠出を前提とする制度であるため、保険料を納付したことのない者に対して年金給付が行われることはない。",a:false,e:"法30条の4。20歳前傷病による障害基礎年金は保険料の拠出を要件としない無拠出制の給付である。",topic:"通則"},
 {id:"X6-224",s:6,q:"20歳前傷病による障害基礎年金の給付に要する費用については、国庫負担の割合が通常の基礎年金より高く設定されている。",a:true,e:"法85条1項。20歳前傷病の障害基礎年金は、その費用の100分の20を別途負担したうえで残りの2分の1も負担する。",topic:"費用"},
 {id:"X6-225",s:6,q:"国庫は、毎年度、予算の範囲内で、国民年金事業の事務の執行に要する費用を負担する。",a:true,e:"法85条2項。事務費は国庫負担。給付費に対する国庫負担(2分の1)とは別枠。",topic:"費用"},
 {id:"X6-226",s:6,q:"国民年金の積立金の運用は、厚生労働大臣が年金積立金管理運用独立行政法人に対し寄託することにより行う。",a:true,e:"法76条。積立金は被保険者の利益のために長期的な観点から安全かつ効率的に運用する(法75条)。",topic:"費用"},
 {id:"X6-227",s:6,q:"国民年金基金が支給する老齢年金の額は、200円に加入員期間の月数を乗じて得た額を超えるものでなければならない。",a:true,e:"法130条2項。基金の年金は付加年金相当額を上回る必要がある。基金は付加年金を代行するため、最低でも付加年金額を上回る必要がある。",topic:"国民年金基金"},
 {id:"X6-228",s:6,q:"国民年金基金が支給する年金は、少なくとも、加入員であった者が老齢基礎年金の受給権を取得したときには、その者に支給されるものでなければならない。",a:true,e:"法130条1項。老齢基礎年金の上乗せ給付としての性格。老齢基礎年金の受給権取得後に支給が開始されないような設計は認められない。",topic:"国民年金基金"},
 {id:"X6-229",s:6,q:"第1号被保険者であれば、保険料の全額免除を受けている者も国民年金基金の加入員となることができる。",a:false,e:"法127条1項。免除者(産前産後免除を除く)や農業者年金の被保険者は加入員となれない。",topic:"国民年金基金"},
 {id:"X6-230",s:6,q:"日本国内に住所を有する60歳以上65歳未満の任意加入被保険者も、国民年金基金の加入員となることができる。",a:true,e:"法附則5条。平成25年4月から任意加入被保険者(海外在住者を含む)も基金に加入できる。",topic:"国民年金基金"},
 {id:"X6-231",s:6,q:"国民年金基金の加入員が保険料の免除(産前産後免除を除く)を受けることになったときは、加入員の資格を喪失する。",a:true,e:"法127条3項。保険料を納付することを要しないものとされたときは加入員資格を喪失する。",topic:"国民年金基金"},
 {id:"X6-232",s:6,q:"被保険者の資格に関する処分が確定したときは、その処分についての不服を当該処分に基づく給付に関する処分についての不服の理由とすることができない。",a:true,e:"法101条4項。資格に関する処分と給付に関する処分の関係。資格処分に不服があれば、その処分自体を争う必要がある。",topic:"不服申立て"},
 {id:"X6-233",s:6,q:"給付に関する処分の取消しの訴えは、社会保険審査会の裁決を経た後でなければ提起することができない。",a:false,e:"法101条の2。社会保険審査官の決定を経た後であれば提起できる。再審査請求を経る必要はない。",topic:"不服申立て"},
 {id:"X6-234",s:6,q:"審査請求及び再審査請求は、時効の完成猶予及び更新に関しては、裁判上の請求とみなされる。",a:true,e:"法101条3項。審査請求等をしている間に時効が完成しないようにするための規定。審査請求期間中に受給権などが時効で消滅するのを防ぐ。",topic:"不服申立て"},
 {id:"X6-235",s:6,q:"被保険者の資格に関する処分に不服がある者は、社会保険審査官を経ずに、直接社会保険審査会に審査請求をしなければならない。",a:false,e:"法101条1項。資格・給付・保険料等の処分は、まず社会保険審査官に審査請求をし、その決定に不服があれば社会保険審査会に再審査請求をする。",topic:"不服申立て"},
 {id:"X6-236",s:6,q:"保険料その他国民年金法の規定による徴収金に関する処分に不服がある者は、社会保険審査官に対して審査請求をすることができる。",a:true,e:"法101条1項。国民年金では保険料等の処分も社会保険審査官・社会保険審査会の二審制。",topic:"不服申立て"},
 {id:"X6-237",s:6,q:"第1号被保険者の資格は、要件に該当した者について厚生労働大臣の確認があったときに、その取得の効力が生じる。",a:false,e:"法8条。国民年金の資格は要件に該当した事実により当然に取得する。健康保険・厚生年金保険のような確認の制度はない。",topic:"被保険者"},
 {id:"X6-238",s:6,q:"第3号被保険者(55歳)の配偶者が、65歳に達し老齢給付の受給権を有することにより第2号被保険者でなくなった場合でも、第3号被保険者の資格には影響しない。",a:false,e:"法7条1項3号・附則3条。第3号は第2号の被扶養配偶者に限られるため、配偶者が第2号でなくなれば第1号への種別変更となる。",topic:"被保険者"},
 {id:"X6-239",s:6,q:"昭和40年4月1日以前生まれで海外に居住する日本国籍を有する65歳以上70歳未満の者は、老齢基礎年金の受給資格期間を満たしていても、特例任意加入被保険者となることができる。",a:false,e:"平成6年・平成16年改正法附則。特例任意加入は老齢基礎年金等の受給権を有しない者(受給資格期間を満たさない者)に限られる。",topic:"被保険者"},
 {id:"X6-240",s:6,q:"第1号被保険者の資格取得の届出は、資格取得日から30日以内に厚生労働大臣に対して行わなければならない。",a:false,e:"法12条1項・則。第1号の資格取得の届出は14日以内に市町村長に対して行う。",topic:"届出・原簿"},
 {id:"X6-241",s:6,q:"督促をした場合の延滞金は、督促状に指定した期限の翌日から徴収金の完納の日の前日までの期間について計算される。",a:false,e:"法97条1項。延滞金は「納期限の翌日」から完納又は財産差押えの日の前日までの日数に応じて計算する。",topic:"保険料"},
 {id:"X6-242",s:6,q:"法定免除は、厚生労働大臣に申請をし、その承認を受けることによって適用される。",a:false,e:"法89条1項。法定免除は要件に該当すれば当然に適用される。事由該当の届出は必要だが承認は要しない。",topic:"保険料の免除"},
 {id:"X6-243",s:6,q:"申請全額免除の承認期間は、原則として4月から翌年3月までを単位とする。",a:false,e:"法90条・則。申請全額免除・一部免除・納付猶予は原則7月から翌年6月まで。4月から翌年3月までを単位とするのは学生納付特例。",topic:"保険料の免除"},
 {id:"X6-244",s:6,q:"保険料納付猶予制度は、30歳未満の第1号被保険者に限り利用することができる。",a:false,e:"平成26年改正法附則14条。平成28年7月から対象が50歳未満に拡大されている(30歳未満は旧制度)。",topic:"保険料の免除"},
 {id:"X6-245",s:6,q:"生活保護法による生活扶助を受ける第1号被保険者の保険料は、申請により全額免除される。",a:false,e:"法89条1項2号。生活扶助の受給者は法定免除。生活扶助以外の扶助の受給者は申請免除(法90条1項2号)。",topic:"保険料の免除"},
 {id:"X6-246",s:6,q:"追納をする場合の保険料の額は、追納をする時点の保険料額による。",a:false,e:"法94条3項・令。免除等を受けた当時の保険料額による。3年度目以降の追納には経過期間に応じた加算額が上乗せされる。",topic:"追納"},
 {id:"X6-247",s:6,q:"保険料の追納は、厚生労働大臣の承認を要さず、被保険者の任意でいつでも行うことができる。",a:false,e:"法94条1項。追納は厚生労働大臣の承認を受けて行う。承認の日の属する月前10年以内の期間に限られる。",topic:"追納"},
 {id:"X6-248",s:6,q:"老齢基礎年金の繰上げ支給の請求をした場合でも、付加年金は繰り上げられず、65歳から減額されない額で支給される。",a:false,e:"法附則9条の2等。付加年金も老齢基礎年金とあわせて繰り上げられ、同じ率で減額される。",topic:"付加年金"},
 {id:"X6-249",s:6,q:"国民年金基金の加入員である第1号被保険者は、申出により付加保険料を納付することができる。",a:false,e:"法87条の2第1項。国民年金基金の加入員は付加保険料を納付できない。基金が付加年金相当部分を代行する。",topic:"付加年金"},
 {id:"X6-250",s:6,q:"老齢基礎年金の受給権者が65歳以後に厚生年金保険の被保険者として就労した場合、その期間に応じて老齢基礎年金の額が改定される。",a:false,e:"法27条。老齢基礎年金の額は原則として20歳以上60歳未満の期間で計算され、65歳以後の就労期間は反映されない。",topic:"老齢基礎年金"},
 {id:"X6-251",s:6,q:"老齢基礎年金の受給権を取得した65歳到達直後であれば、1年を経過する前であっても繰下げの申出をすることができる。",a:false,e:"法28条1項。繰下げの申出ができるのは66歳に達する前に老齢基礎年金を請求していなかった者であり、66歳到達前(受給権取得から1年経過前)には申出できない。",topic:"繰上げ・繰下げ"},
 {id:"X6-252",s:6,q:"振替加算の対象者が障害基礎年金の支給を受けることができるときであっても、振替加算は支給停止されない。",a:false,e:"昭和60年改正法附則16条。障害基礎年金等の支給を受けることができる間は、振替加算に相当する部分の支給が停止される。",topic:"振替加算"},
 {id:"X6-253",s:6,q:"20歳前傷病による障害基礎年金は、障害認定日が20歳到達日前にあるときは、20歳に達した日の属する月から支給される。",a:false,e:"法30条の4・18条1項。20歳到達日に受給権が発生し、その翌月から支給される。",topic:"障害基礎年金"},
 {id:"X6-254",s:6,q:"障害基礎年金の子の加算の対象となっている子(障害の状態にない)が18歳に達したときは、その翌月から加算額が減額される。",a:false,e:"法33条の2第3項。18歳に達する日以後の最初の3月31日が終了したときに減額事由となる。障害状態の子は20歳到達時。",topic:"障害基礎年金"},
 {id:"X6-255",s:6,q:"事後重症による障害基礎年金の請求は、障害認定日から5年以内に行わなければならない。",a:false,e:"法30条の2。65歳に達する日の前日までに2級以上に該当し、その期間内に請求すれば足りる。",topic:"障害基礎年金"},
 {id:"X6-256",s:6,q:"障害基礎年金の受給権者の障害の程度が軽快し、障害等級3級に該当する程度になったときは、その時点で受給権は消滅する。",a:false,e:"法36条2項・35条。2級に該当しなくなった間は支給停止となるにとどまり、直ちに失権するわけではない。",topic:"障害基礎年金"},
 {id:"X6-257",s:6,q:"遺族基礎年金の受給権を有する配偶者と子がいる場合、遺族基礎年金は配偶者と子に等分して支給される。",a:false,e:"法39条・41条2項。配偶者に子の加算を含めた額が支給され、子に対する遺族基礎年金は支給停止となる。",topic:"遺族基礎年金"},
 {id:"X6-258",s:6,q:"被保険者が死亡した場合の遺族基礎年金の保険料納付要件は、死亡日において、死亡日の属する月の前月までの被保険者期間で判定する。",a:false,e:"法37条ただし書。死亡日の前日において、死亡日の属する月の前々月までの被保険者期間で判定する。",topic:"遺族基礎年金"},
 {id:"X6-259",s:6,q:"遺族基礎年金の受給権者である妻が、死亡した夫の父の養子となったときは、その受給権は消滅する。",a:false,e:"法40条1項3号。夫の父は妻にとって直系姻族であり、直系血族又は直系姻族の養子となっても失権しない。",topic:"遺族基礎年金"},
 {id:"X6-260",s:6,q:"寡婦年金の支給要件である夫の保険料納付済期間等の計算には、夫の第2号被保険者としての被保険者期間も算入される。",a:false,e:"法49条1項。算入されるのは第1号被保険者としての被保険者期間に係る保険料納付済期間・保険料免除期間のみ。",topic:"寡婦年金"},
 {id:"X6-261",s:6,q:"死亡一時金を受けるべき同順位の遺族が2人以上あるときは、そのうちの年長者に全額が支給される。",a:false,e:"法52条の3。同順位者が2人以上あるときは、1人のした請求は全員のためにしたものとみなし、1人に対する支給は全員に対するものとみなす。",topic:"死亡一時金"},
 {id:"X6-262",s:6,q:"脱退一時金は、日本国籍を有する者であっても、海外に移住する場合には請求することができる。",a:false,e:"法附則9条の3の2。脱退一時金を請求できるのは日本国籍を有しない者に限られる。",topic:"脱退一時金"},
 {id:"X6-263",s:6,q:"障害基礎年金の受給権を有したことがある者であっても、脱退一時金を請求することができる。",a:false,e:"法附則9条の3の2。障害基礎年金その他政令で定める給付の受給権を有したことがある者は請求できない。",topic:"脱退一時金"},
 {id:"X6-264",s:6,q:"老齢基礎年金と付加年金の受給権者が障害基礎年金を選択して受給している場合でも、付加年金は支給される。",a:false,e:"法20条・47条。付加年金は老齢基礎年金と一体であり、老齢基礎年金が全額停止されている間は付加年金も停止される。",topic:"併給調整"},
 {id:"X6-265",s:6,q:"未支給年金を請求できる遺族は、死亡した受給権者によって生計を維持されていた者に限られる。",a:false,e:"法19条1項。要件は死亡の当時生計を同じくしていたこと。生計維持(収入要件)までは求められない。",topic:"通則"},
 {id:"X6-266",s:6,q:"年金給付を受ける権利は、担保に供することはできないが、他人に譲り渡すことはできる。",a:false,e:"法24条。給付を受ける権利は、譲り渡し、担保に供し、又は差し押さえることができない。老齢基礎年金・付加年金を国税滞納処分により差し押さえる場合は例外。",topic:"通則"},
 {id:"X6-267",s:6,q:"社会保険審査官に対する審査請求は、処分があったことを知った日の翌日から起算して1年以内にしなければならない。",a:false,e:"社会保険審査官及び社会保険審査会法4条1項。原則として処分があったことを知った日の翌日から3月以内。",topic:"不服申立て"},
 {id:"X6-268",s:6,q:"第3号被保険者は、申出により国民年金基金の加入員となることができる。",a:false,e:"法127条1項。加入員となれるのは第1号被保険者(免除者等を除く)と任意加入被保険者。第3号は加入できない。",topic:"国民年金基金"},
 {id:"X6-269",s:6,q:"付加年金の給付に要する費用については、国庫負担は行われない。",a:false,e:"法85条1項。付加年金の給付に要する費用等についても、その4分の1を国庫が負担する。",topic:"費用"},
 {id:"X6-270",s:6,q:"老齢基礎年金の受給資格期間を判定する際、学生納付特例期間は算入されない。",a:false,e:"法26条・5条2項。学生納付特例期間は保険料免除期間として受給資格期間に算入される。年金額には追納しない限り反映されない。",topic:"受給資格期間"},
 {id:"XT6-01",s:6,format:"choice",examFmt:true,topic:"被保険者の資格",difficulty:2,q:"国民年金の被保険者の資格の取得・喪失及び被保険者期間に関する次の記述のうち、正しいものはどれか。",choices:[{t:"20歳以上60歳未満の者が日本国内に住所を有するに至ったときは、その日に第1号被保険者の資格を取得する。",ok:1,why:"正しい。国内に住所を有するに至った日に取得する(法8条)。"},{t:"被保険者が死亡したときは、死亡した日に被保険者の資格を喪失する。",ok:0,why:"誤り。死亡の場合は死亡した日の翌日に喪失する(法9条)。"},{t:"同一の月において種別の変更があったときは、その月は変更前の種別の被保険者であった月とみなされる。",ok:0,why:"誤り。変更後(2回以上なら最後)の種別の被保険者であった月とみなす(法11条の2)。"},{t:"被保険者期間は、資格を取得した日の属する月の翌月から算入する。",ok:0,why:"誤り。資格取得月から資格喪失月の前月までを算入する(法11条1項)。"},{t:"第1号被保険者が60歳に達したときは、その翌日に被保険者の資格を喪失する。",ok:0,why:"誤り。60歳到達は「その日」に喪失する(法9条)。翌日喪失は死亡・国内住所の喪失など。"}],memoryPoint:"年齢到達は当日、死亡・国内住所喪失は翌日。被保険者期間は取得月から喪失月の前月まで。同月内の種別変更は最後の種別。",trap:"当日喪失と翌日喪失の入替え、取得月を「翌月」から算入とする改変が定番。",e:"国内住所取得日に第1号の資格取得(法8条)。"},
 {id:"XT6-02",s:6,format:"choice",examFmt:true,topic:"任意加入被保険者",difficulty:2,q:"任意加入被保険者に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"任意加入被保険者(特例任意加入被保険者を除く)は、付加保険料を納付することができる。",ok:0,why:"正しい。任意加入被保険者は第1号とみなされ付加保険料を納付できる。特例任意加入者は不可。"},{t:"任意加入被保険者は、厚生労働大臣に申し出た日に資格を取得する。",ok:0,why:"正しい。申出をした日に取得する(附則5条)。"},{t:"任意加入被保険者は、所得が一定額以下であれば、保険料の申請全額免除を受けることができる。",ok:1,why:"誤り。任意加入被保険者には法定免除・申請免除・学生納付特例・納付猶予の適用がない(附則5条)。"},{t:"任意加入被保険者は、いつでも厚生労働大臣に申し出て資格を喪失することができる。",ok:0,why:"正しい。申出が受理された日に喪失する(附則5条)。"},{t:"日本国内に住所を有する60歳以上65歳未満の者は、任意加入被保険者となることができる。",ok:0,why:"正しい。附則5条1項2号。老齢給付等の受給の有無は問わない(第2号等を除く)。"}],memoryPoint:"任意加入は申出日に取得・いつでも脱退可。免除制度の適用なし。付加保険料は納付可(特例任意加入は不可)。",trap:"免除が使えない代わりにいつでも脱退できる、という対の関係を崩してくる。",e:"任意加入被保険者に免除の適用なし(附則5条)。"},
 {id:"XT6-03",s:6,format:"choice",examFmt:true,topic:"届出・国民年金原簿",difficulty:2,q:"届出等に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"令和4年4月以降に新たに被保険者となった者には、国民年金手帳が交付される。",ok:1,why:"誤り。国民年金手帳は令和4年4月に廃止され、基礎年金番号通知書が送付される。"},{t:"第1号被保険者は、資格の取得・喪失等に関する事項を、原則として14日以内に市町村長に届け出なければならない。",ok:0,why:"正しい。法12条1項・則。第1号の届出先は市町村長。"},{t:"被保険者は、国民年金原簿に記録された自己の記録が事実でないと思料するときは、厚生労働大臣に訂正の請求をすることができる。",ok:0,why:"正しい。法14条の2。"},{t:"第3号被保険者の届出の遅滞にやむを得ない事由があると認められるときは、届出により、2年より前の期間も保険料納付済期間に算入される。",ok:0,why:"正しい。附則7条の3第2項の特例届出。"},{t:"第1号被保険者の属する世帯の世帯主は、被保険者に代わって資格の取得等の届出をすることができる。",ok:0,why:"正しい。法12条2項。"}],memoryPoint:"第1号の届出は14日以内に市町村長(世帯主の代理届出可)。第3号の遅れは2年まで、やむを得ない事由があれば特例届出。年金手帳は令和4年4月廃止。",trap:"令和4年の年金手帳廃止を知らないと、古い知識のまま正しいと判断してしまう。",e:"年金手帳は令和4年4月廃止。"},
 {id:"XT6-04",s:6,format:"choice",examFmt:true,topic:"保険料の納付",difficulty:2,q:"保険料の納付等に関する次の記述のうち、正しいものはどれか。",choices:[{t:"第1号被保険者の保険料の額は、前年の所得に応じて定められる。",ok:0,why:"誤り。所得にかかわらず定額(法87条)。"},{t:"第1号被保険者の毎月の保険料の納期限は、その月の末日である。",ok:0,why:"誤り。納期限は翌月末日(法91条)。"},{t:"保険料を徴収する権利は、5年を経過したときは時効によって消滅する。",ok:0,why:"誤り。保険料徴収権の時効は2年(法102条4項)。"},{t:"前納された保険料は、前納に係る期間の各月が経過した際に、それぞれその月の保険料が納付されたものとみなされる。",ok:1,why:"正しい。法93条3項。"},{t:"督促状により指定する期限は、督促状を発する日から起算して7日以上を経過した日でなければならない。",ok:0,why:"誤り。10日以上を経過した日でなければならない(法96条3項)。"}],memoryPoint:"納期限は翌月末日。前納は各月が経過した際に納付みなし。督促の期限は10日以上、徴収権の時効は2年。",trap:"月末と翌月末、7日と10日、2年と5年という数字の入替えが狙われる。",e:"前納保険料は各月経過時に納付みなし(法93条3項)。"},
 {id:"XT6-05",s:6,format:"choice",examFmt:true,topic:"法定免除",difficulty:3,q:"保険料の法定免除に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"障害等級2級に該当する障害基礎年金の受給権者は、法定免除の対象となる。",ok:0,why:"正しい。法89条1項1号。20歳前傷病によるものも含む。"},{t:"法定免除の期間は、事由に該当するに至った日の属する月から、該当しなくなる日の属する月の前月までである。",ok:1,why:"誤り。該当するに至った日の属する月の「前月」から、該当しなくなる日の属する月「まで」(法89条1項)。"},{t:"法定免除の対象者であっても、申出をすれば法定免除期間の保険料を納付することができる。",ok:0,why:"正しい。法89条2項(平成26年4月〜)。"},{t:"国立ハンセン病療養所等の施設に入所している者は、法定免除の対象となる。",ok:0,why:"正しい。法89条1項3号。"},{t:"生活保護法による生活扶助を受けるに至った第1号被保険者は、法定免除の対象となる。",ok:0,why:"正しい。法89条1項2号。生活扶助以外の扶助は申請免除の事由。"}],memoryPoint:"法定免除は該当月の前月から、非該当月まで。申出すれば納付も可能。",trap:"始期と終期を1か月ずつずらす改変が定番。資格喪失の「喪失月の前月まで」と混同させる。",e:"法定免除は前月から該当しなくなる月まで(法89条)。"},
 {id:"XT6-06",s:6,format:"choice",examFmt:true,topic:"申請免除・学生納付特例・納付猶予",difficulty:3,q:"保険料の申請免除・学生納付特例・納付猶予に関する次の記述のうち、正しいものはどれか。",choices:[{t:"学生納付特例期間は、追納しなくても老齢基礎年金の額に2分の1が反映される。",ok:0,why:"誤り。追納しない限り年金額には反映されない(法27条)。"},{t:"一部免除の承認を受けた者が残りの保険料を納付しなかった期間も、保険料免除期間となる。",ok:0,why:"誤り。残余を納付した場合に限り免除期間となり、未納なら未納期間(法5条)。"},{t:"学生納付特例の対象となる学生等は、所得が低ければ申請全額免除を選択することもできる。",ok:0,why:"誤り。学生等である期間は申請免除の対象外(法90条1項)。"},{t:"学生納付特例の所得審査は、学生本人の所得のみで行われる。",ok:1,why:"正しい。法90条の3。親(世帯主)の所得は問われない。"},{t:"保険料納付猶予の所得審査では、本人・配偶者に加えて世帯主の所得も審査される。",ok:0,why:"誤り。納付猶予は本人と配偶者の所得で判定し、世帯主の所得は問わない(平成26年改正法附則14条)。"}],memoryPoint:"申請免除=本人・配偶者・世帯主、納付猶予=本人・配偶者、学生納付特例=本人のみ。学生特例・猶予は年金額に反映なし。",trap:"誰の所得で審査するかを入れ替えてくる。三者の比較表で覚える。",e:"学生納付特例は本人所得のみ(法90条の3)。"},
 {id:"XT6-07",s:6,format:"choice",examFmt:true,topic:"追納",difficulty:3,q:"保険料の追納に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"産前産後期間の免除を受けた期間の保険料も、追納することができる。",ok:1,why:"誤り。産前産後免除期間は保険料納付済期間とされるため追納の対象外。"},{t:"追納は、厚生労働大臣の承認を受けた日の属する月前10年以内の期間に限り行うことができる。",ok:0,why:"正しい。法94条1項。"},{t:"老齢基礎年金の受給権者は、保険料を追納することができない。",ok:0,why:"正しい。法94条1項ただし書。"},{t:"追納が行われたときは、追納が行われた日に追納に係る月の保険料が納付されたものとみなされる。",ok:0,why:"正しい。法94条4項。"},{t:"免除を受けた年度の翌年度から起算して3年度目以降に追納する場合には、政令で定める額が加算される。",ok:0,why:"正しい。法94条3項・令。"}],memoryPoint:"追納は承認月前10年以内、老齢基礎年金の受給権者は不可、追納日に納付みなし。産前産後免除は追納不要(納付済扱い)。",trap:"産前産後免除を他の免除と同列に扱わせる肢が狙い目。",e:"産前産後免除期間は追納の対象外。"},
 {id:"XT6-08",s:6,format:"choice",examFmt:true,topic:"産前産後期間の保険料免除",difficulty:3,q:"第1号被保険者の産前産後期間の保険料免除に関する次の記述のうち、正しいものはどれか。",choices:[{t:"産前産後免除期間は保険料納付済期間として扱われ、その期間中も付加保険料を納付し、国民年金基金に加入することができる。",ok:1,why:"正しい。法88条の2・5条1項。"},{t:"多胎妊娠の場合の免除期間は、出産予定日の属する月の前月から6か月間である。",ok:0,why:"誤り。多胎妊娠は出産予定月の3か月前から6か月間。"},{t:"妊娠85日以上であっても、死産や流産の場合は免除の対象とならない。",ok:0,why:"誤り。妊娠85日以上の出産であれば死産・流産等も対象。"},{t:"免除の対象は、出産予定日の属する月から4か月間である。",ok:0,why:"誤り。出産予定日(出産日)の属する月の前月から4か月間(法88条の2)。"},{t:"産前産後期間の保険料免除には、前年の所得が一定額以下であることが要件とされている。",ok:0,why:"誤り。所得要件はない。届出により適用される(法88条の2)。"}],memoryPoint:"産前産後免除=前月から4か月(多胎は3か月前から6か月)、所得要件なし、納付済期間扱い。",trap:"期間の起点(前月/3か月前)と、所得要件の有無を崩してくる。",e:"産前産後免除は納付済期間扱い(法88条の2)。"},
 {id:"XT6-09",s:6,format:"choice",examFmt:true,topic:"受給資格期間・合算対象期間",difficulty:3,q:"老齢基礎年金の受給資格期間及び合算対象期間に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"昭和61年4月以降に海外に居住していた日本人の20歳以上60歳未満の期間は、任意加入しなかった場合、合算対象期間とならない。",ok:1,why:"誤り。海外在住日本人の任意未加入期間(20歳以上60歳未満)は合算対象期間となる。"},{t:"受給資格期間の10年には、合算対象期間も算入される。",ok:0,why:"正しい。法26条・附則9条。"},{t:"平成3年3月以前の学生で任意加入しなかった20歳以上60歳未満の期間は、合算対象期間となる。",ok:0,why:"正しい。学生の強制加入は平成3年4月から。"},{t:"昭和61年3月以前の被用者年金制度の加入者の配偶者で任意加入しなかった20歳以上60歳未満の期間は、合算対象期間となる。",ok:0,why:"正しい。昭和60年改正法附則8条5項。"},{t:"第2号被保険者期間のうち20歳前及び60歳以後の期間は、老齢基礎年金においては合算対象期間として扱われる。",ok:0,why:"正しい。昭和60年改正法附則8条4項・5項。"}],memoryPoint:"カラ期間=資格期間には入るが額には入らない。旧法の任意未加入(配偶者・学生)、海外在住日本人、第2号の20歳前・60歳以後。",trap:"海外在住期間を「任意加入しなければ何も残らない」と思わせる肢が定番。",e:"海外在住日本人の任意未加入期間は合算対象期間。"},
 {id:"XT6-10",s:6,format:"choice",examFmt:true,topic:"老齢基礎年金の額",difficulty:3,q:"老齢基礎年金の額の計算に関する次の記述のうち、正しいものはどれか。",choices:[{t:"学生納付特例期間は、追納しなくても2分の1が反映される。",ok:0,why:"誤り。追納しない限り反映されない。"},{t:"60歳以後に任意加入して保険料を納付した期間は、老齢基礎年金の額に反映されない。",ok:0,why:"誤り。任意加入の納付済期間は年金額に反映される(上限480月)。"},{t:"平成21年4月以降の保険料全額免除期間は、3分の1として反映される。",ok:0,why:"誤り。平成21年4月以降は2分の1(8分の4)。3分の1は平成21年3月以前。"},{t:"平成21年3月以前の保険料半額免除期間は、3分の2として反映される。",ok:1,why:"正しい。国庫負担3分の1時代の反映割合(平成16年改正法附則)。"},{t:"平成21年4月以降の保険料4分の1免除期間は、6分の5として反映される。",ok:0,why:"誤り。平成21年4月以降は8分の7。6分の5は平成21年3月以前。"}],memoryPoint:"平成21年4月以降:全額4/8・3/4免除5/8・半額6/8・1/4免除7/8。平成21年3月以前:1/3・1/2・2/3・5/6。",trap:"新旧の反映割合を入れ替えてくる。国庫負担割合(1/3→1/2)から逆算できるようにする。",e:"平成21年3月以前の半額免除は3分の2。"},
 {id:"XT6-11",s:6,format:"choice",examFmt:true,topic:"繰上げ支給",difficulty:3,q:"老齢基礎年金の支給繰上げに関する次の記述のうち、誤っているものはどれか。",choices:[{t:"寡婦年金の受給権者が繰上げ支給の老齢基礎年金の受給権を取得したときは、寡婦年金の受給権は消滅する。",ok:0,why:"正しい。附則9条の2。"},{t:"老齢厚生年金の繰上げ請求をすることができる者は、老齢基礎年金の繰上げ請求を老齢厚生年金の繰上げ請求と同時に行わなければならない。",ok:0,why:"正しい。附則9条の2第2項。"},{t:"繰上げ請求をした者は、65歳に達するまでの間であれば、その請求を取り消して65歳から本来の額で受給することができる。",ok:1,why:"誤り。繰上げ請求は取り消すことができず、減額は生涯続く。"},{t:"繰上げ支給を受けている者は、事後重症による障害基礎年金を請求することができない。",ok:0,why:"正しい。附則9条の2の3。65歳に達したものとみなされる。"},{t:"任意加入被保険者である間は、支給繰上げの請求をすることができない。",ok:0,why:"正しい。附則9条の2第1項。"}],memoryPoint:"繰上げのデメリット:取消不可・事後重症/基準障害の請求不可・寡婦年金失権・任意加入不可。",trap:"デメリット列挙の中に、実際には存在しない救済(取消し)を紛れ込ませる。",e:"繰上げ請求は取消し不可。"},
 {id:"XT6-12",s:6,format:"choice",examFmt:true,topic:"繰下げ支給",difficulty:3,q:"老齢基礎年金の支給繰下げに関する次の記述のうち、正しいものはどれか。",choices:[{t:"繰下げの申出をした場合、増額された年金は申出をした日の属する月から支給される。",ok:0,why:"誤り。申出のあった日の属する月の翌月から支給(法28条3項)。"},{t:"66歳に達する前に障害基礎年金の受給権者となった者も、繰下げの申出をすることができる。",ok:0,why:"誤り。65歳到達時又は65歳から66歳までの間に他の年金たる給付(付加年金を除く)の受給権者であった者は申出不可(法28条1項ただし書)。"},{t:"繰下げによる増額率は、1月につき1000分の5である。",ok:0,why:"誤り。1000分の7(令4条の5)。最大120月で84%。"},{t:"繰下げの申出をしても、付加年金は増額されない。",ok:0,why:"誤り。付加年金も同率で増額される(法46条)。"},{t:"70歳に達した日後に請求し繰下げの申出をしないときは、原則として請求日の5年前の日に繰下げの申出があったものとみなされる。",ok:1,why:"正しい。法28条5項(令和5年4月施行)。"}],memoryPoint:"繰下げは申出月の翌月から、月0.7%(最大84%)。70歳後の請求は5年前にみなし繰下げ。付加年金も連動。",trap:"支給開始月と増額率、付加年金の連動の有無を崩す。",e:"70歳後請求は5年前みなし繰下げ(法28条5項)。"},
 {id:"XT6-13",s:6,format:"choice",examFmt:true,topic:"振替加算",difficulty:3,q:"振替加算に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"振替加算は、配偶者の老齢厚生年金の加給年金額の対象となっていた者が65歳に達したときに、その者の老齢基礎年金に加算される。",ok:0,why:"正しい。昭和60年改正法附則14条。"},{t:"振替加算の額は、受給権者の生年月日にかかわらず一定である。",ok:1,why:"誤り。生年月日に応じた率(1.000〜0.067)を乗じて算定し、若い世代ほど少ない。"},{t:"振替加算の対象となるのは、原則として大正15年4月2日から昭和41年4月1日までの間に生まれた者である。",ok:0,why:"正しい。附則14条。"},{t:"受給権者本人が被保険者期間20年以上の老齢厚生年金を受けることができるときは、振替加算は加算されない。",ok:0,why:"正しい。附則14条1項ただし書。"},{t:"合算対象期間と学生納付特例期間のみで受給資格期間を満たす者にも、振替加算相当額の老齢基礎年金が支給されることがある。",ok:0,why:"正しい。附則15条。"}],memoryPoint:"振替加算=加給年金の対象者が65歳になると本人の老齢基礎年金へ振替。生年月日で逓減、昭和41年4月2日以後生まれは対象外。",trap:"定額と思わせる肢が定番。生年月日による逓減の趣旨(第3号制度で加入できた期間の差)を押さえる。",e:"振替加算は生年月日で逓減。"},
 {id:"XT6-14",s:6,format:"choice",examFmt:true,topic:"付加保険料・付加年金",difficulty:3,q:"付加保険料及び付加年金に関する次の記述のうち、正しいものはどれか。",choices:[{t:"付加年金は、老齢基礎年金が全額支給停止されている間も支給される。",ok:0,why:"誤り。老齢基礎年金の全額停止中は付加年金も停止(法47条)。"},{t:"老齢基礎年金の繰下げの申出をしても、付加年金は増額されない。",ok:0,why:"誤り。同率で増額される(法46条)。"},{t:"付加保険料を納付する申出をした場合、申出をした日の属する月の翌月から納付する者となる。",ok:0,why:"誤り。申出をした日の属する月以後の各月について納付する者となる(法87条の2第1項)。"},{t:"付加保険料を納付する者が国民年金基金の加入員となったときは、その日に付加保険料を納付する者でなくなる旨の申出をしたものとみなされる。",ok:1,why:"正しい。法87条の2第4項。"},{t:"保険料の半額免除を受けている者も、付加保険料を納付することができる。",ok:0,why:"誤り。一部免除者も納付できない(法87条の2第1項)。"}],memoryPoint:"付加保険料は第1号(免除者・基金加入員を除く)と任意加入者。付加年金は老齢基礎年金と一体(繰上げ・繰下げ・停止が連動)。",trap:"付加年金を独立した年金のように扱わせる肢に注意。",e:"基金加入で付加保険料の辞退みなし(法87条の2第4項)。"},
 {id:"XT6-15",s:6,format:"choice",examFmt:true,topic:"障害基礎年金の支給要件",difficulty:3,q:"障害基礎年金の支給要件に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"障害認定日は、初診日から起算して1年6月を経過した日又はその期間内に傷病が治った日である。",ok:0,why:"正しい。法30条1項。症状固定日を含む。"},{t:"初診日に被保険者でなくても、被保険者であった者で日本国内に住所を有する60歳以上65歳未満の者であれば支給対象となりうる。",ok:0,why:"正しい。法30条1項2号。"},{t:"初診日とは、その傷病について初めて医師又は歯科医師の診療を受けた日をいう。",ok:0,why:"正しい。法30条1項。"},{t:"初診日に被保険者であれば、海外に居住していても支給対象となりうる。",ok:0,why:"正しい。法30条1項1号。国内住所要件は60歳以上65歳未満の非被保険者のみ。"},{t:"保険料納付要件の3分の2要件の判定においては、合算対象期間も保険料納付済期間とあわせて算入される。",ok:1,why:"誤り。納付済期間と免除期間で判定し、合算対象期間は算入しない(法30条1項ただし書)。"}],memoryPoint:"初診日要件(被保険者 or 60〜65歳の国内居住者)・障害認定日要件(1年6月)・納付要件(前日に前々月まで3分の2)。",trap:"合算対象期間を納付要件に紛れ込ませる肢。カラ期間は老齢基礎年金の資格期間用。",e:"3分の2要件に合算対象期間は含まない。"},
 {id:"XT6-16",s:6,format:"choice",examFmt:true,topic:"障害基礎年金の加算・支給停止・失権",difficulty:4,q:"障害基礎年金の加算・支給停止・失権に関する次の記述のうち、正しいものはどれか。",choices:[{t:"同一の傷病について労災保険の障害補償年金を受けるときは、障害基礎年金が6年間支給停止される。",ok:0,why:"誤り。6年間の停止は労働基準法の障害補償の場合(法36条1項)。労災年金とは労災側で減額調整。"},{t:"障害等級3級にも該当しないまま、65歳に達した日と3級不該当となってから3年を経過した日のいずれか遅い日が到来したときに、受給権は消滅する。",ok:1,why:"正しい。法35条。"},{t:"障害基礎年金には、受給権者によって生計を維持している配偶者に係る加算がある。",ok:0,why:"誤り。障害基礎年金の加算は子のみ。配偶者加給年金額は障害厚生年金(1・2級)。"},{t:"受給権取得後に生まれた子については、子の加算は行われない。",ok:0,why:"誤り。平成23年4月以降は受給権取得後に生計維持の子を有するに至った場合も加算される(法33条の2第2項)。"},{t:"事後重症による障害基礎年金は、障害認定日の属する月の翌月まで遡って支給される。",ok:0,why:"誤り。請求月の翌月から支給(法30条の2)。"}],memoryPoint:"子の加算は後から生まれた子も対象。6年停止は労基法の障害補償。失権は「65歳と3年経過の遅い方」。",trap:"労基法と労災保険の入替え、事後重症の遡及の有無が狙われる。",e:"65歳と3年経過の遅い方で失権(法35条)。"},
 {id:"XT6-17",s:6,format:"choice",examFmt:true,topic:"20歳前傷病による障害基礎年金",difficulty:3,q:"20歳前傷病による障害基礎年金に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"受給権者が刑事施設等に拘禁されている場合など一定の場合には支給が停止される。",ok:0,why:"正しい。法36条の2第1項。"},{t:"初診日に20歳未満であった者(被保険者でなかった者)については、保険料納付要件は問われない。",ok:0,why:"正しい。法30条の4。"},{t:"障害認定日が20歳到達日前にあるときは、20歳に達した日に受給権が発生する。",ok:0,why:"正しい。法30条の4第1項。"},{t:"受給権者が日本国内に住所を有しなくなっても、支給は停止されない。",ok:1,why:"誤り。国内に住所を有しないときは支給停止(法36条の2第1項)。"},{t:"受給権者本人の前年の所得が一定額を超えるときは、その全部又は2分の1が支給停止される。",ok:0,why:"正しい。法36条の3。"}],memoryPoint:"20歳前傷病は無拠出の代わりに、所得・拘禁・国外居住・他の公的年金などによる支給停止がある。",trap:"一般の障害基礎年金にはない停止事由を、20歳前傷病にも「ない」と言わせる。",e:"国外居住で支給停止(法36条の2)。"},
 {id:"XT6-18",s:6,format:"choice",examFmt:true,topic:"遺族基礎年金の支給要件・遺族",difficulty:3,q:"遺族基礎年金の支給要件及び遺族の範囲に関する次の記述のうち、正しいものはどれか。",choices:[{t:"老齢基礎年金の受給権者が死亡したときは、保険料納付済期間等の長さにかかわらず遺族基礎年金の支給要件を満たす。",ok:0,why:"誤り。納付済期間等の合計が25年以上ある者に限られる(法37条3号)。"},{t:"被保険者であった者で日本国内に住所を有しない60歳以上65歳未満の者が死亡した場合も、支給要件を満たす。",ok:0,why:"誤り。60歳以上65歳未満の非被保険者は国内住所が要件(法37条2号)。"},{t:"死亡した者と養子縁組をしていない配偶者の連れ子も、遺族となる子に含まれる。",ok:0,why:"誤り。子は死亡した者の子に限られる。"},{t:"被保険者の死亡当時胎児であった子が生まれたときは、将来に向かって、その子は死亡当時生計を維持されていたものとみなされる。",ok:1,why:"正しい。法37条の2第2項。"},{t:"子のない妻も、夫の死亡当時生計を維持されていれば遺族基礎年金を受けることができる。",ok:0,why:"誤り。配偶者は子と生計を同じくすることが要件(法37条の2)。"}],memoryPoint:"遺族基礎年金=子のある配偶者又は子。長期要件は25年以上。胎児は出生時から将来に向かってみなす。",trap:"老齢基礎年金の受給資格期間10年と遺族基礎年金の長期要件25年を混同させる。",e:"胎児は将来に向かって生計維持みなし(法37条の2第2項)。"},
 {id:"XT6-19",s:6,format:"choice",examFmt:true,topic:"遺族基礎年金の失権・支給停止",difficulty:3,q:"遺族基礎年金の失権及び支給停止に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"障害等級に該当する障害の状態にある子の受給権は、その子が20歳に達したときに消滅する。",ok:0,why:"正しい。法40条3項。"},{t:"受給権者が直系血族又は直系姻族以外の者の養子となったときは、受給権は消滅する。",ok:0,why:"正しい。法40条1項3号。"},{t:"配偶者の所在が1年以上明らかでないときは、厚生労働大臣の職権によりその支給が停止される。",ok:1,why:"誤り。受給権を有する子の申請によって、所在不明となった時にさかのぼって停止される(法41条の2)。"},{t:"受給権者が婚姻をしたときは、受給権は消滅する。",ok:0,why:"正しい。法40条1項2号。事実婚を含む。"},{t:"被保険者等の死亡について労働基準法の遺族補償が行われるべきときは、死亡日から6年間支給が停止される。",ok:0,why:"正しい。法41条1項。"}],memoryPoint:"失権=婚姻・直系血族/姻族以外の養子・子の年齢到達等。所在不明の停止は申請による(職権ではない)。",trap:"所在不明による停止を職権とする改変、養子の範囲の入替えが定番。",e:"配偶者の所在不明停止は子の申請による。"},
 {id:"XT6-20",s:6,format:"choice",examFmt:true,topic:"寡婦年金・死亡一時金",difficulty:3,q:"寡婦年金及び死亡一時金に関する次の記述のうち、正しいものはどれか。",choices:[{t:"死亡一時金を受ける権利は、5年を経過したときは時効によって消滅する。",ok:0,why:"誤り。2年(法102条4項)。"},{t:"死亡一時金の36月の要件の計算では、保険料全額免除期間の月数も算入される。",ok:0,why:"誤り。全額免除期間は算入されない。一部免除期間は納付割合に応じて算入(法52条の2)。"},{t:"寡婦年金の額は、夫の第1号被保険者期間に係る老齢基礎年金の額の2分の1である。",ok:0,why:"誤り。4分の3(法50条)。"},{t:"寡婦年金は、夫との婚姻関係が5年以上継続した妻に支給される。",ok:0,why:"誤り。婚姻関係10年以上(法49条1項)。"},{t:"死亡一時金を受けることができる遺族は、死亡当時その者と生計を同じくしていた配偶者、子、父母、孫、祖父母又は兄弟姉妹である。",ok:1,why:"正しい。法52条の3。"}],memoryPoint:"寡婦年金=夫の第1号期間10年以上・婚姻10年以上・60〜65歳・4分の3。死亡一時金=36月以上・生計同一の遺族・時効2年。",trap:"10年と5年、4分の3と2分の1、2年と5年の数字の入替え。",e:"死亡一時金の遺族は生計同一の6者(法52条の3)。"},
 {id:"XT6-21",s:6,format:"choice",examFmt:true,topic:"併給調整・給付制限",difficulty:3,q:"併給調整及び給付の制限等に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"65歳以上の者は、遺族基礎年金と老齢厚生年金を併給することができる。",ok:1,why:"誤り。遺族基礎年金と老齢厚生年金は併給されない。"},{t:"給付事由が第三者の行為によって生じた場合、政府は給付の価額の限度で受給権者の損害賠償請求権を取得する。",ok:0,why:"正しい。法22条1項。"},{t:"受給権者の申出による支給停止は、いつでも将来に向かって撤回することができる。",ok:0,why:"正しい。法20条の2。"},{t:"故意に障害又はその直接の原因となった事故を生じさせた者の当該障害については、障害基礎年金を支給しない。",ok:0,why:"正しい。法69条。"},{t:"65歳以上の者は、老齢基礎年金と遺族厚生年金を併給することができる。",ok:0,why:"正しい。法20条・附則9条の2の4。"}],memoryPoint:"65歳以後の併給:老齢基礎+遺族厚生、障害基礎+老齢厚生、障害基礎+遺族厚生。遺族基礎+老齢厚生は不可。",trap:"65歳以後の併給パターンに存在しない組合せを混ぜる。",e:"遺族基礎+老齢厚生は併給不可。"},
 {id:"XT6-22",s:6,format:"choice",examFmt:true,topic:"脱退一時金・国民年金基金・不服申立て",difficulty:4,q:"脱退一時金、国民年金基金及び不服申立てに関する次の記述のうち、正しいものはどれか。",choices:[{t:"国民年金基金が支給する老齢年金の額は、200円に加入員期間の月数を乗じて得た額を超えるものでなければならない。",ok:1,why:"正しい。法130条2項。"},{t:"保険料の全額免除を受けている第1号被保険者も、国民年金基金の加入員となることができる。",ok:0,why:"誤り。免除者(産前産後免除を除く)は加入員となれない(法127条1項)。"},{t:"給付に関する処分の取消しの訴えは、社会保険審査会の裁決を経た後でなければ提起することができない。",ok:0,why:"誤り。社会保険審査官の決定を経た後であれば提起できる(法101条の2)。"},{t:"脱退一時金は、最後に被保険者の資格を喪失した日から5年以内に請求しなければならない。",ok:0,why:"誤り。2年以内(附則9条の3の2)。"},{t:"国民年金基金は、老齢に関する年金のほか、障害に関する年金も支給する。",ok:0,why:"誤り。基金の給付は老齢に関する年金と死亡に関する一時金。"}],memoryPoint:"脱退一時金は2年以内。基金は老齢年金+死亡一時金、付加年金相当額超え。取消訴訟は審査官の決定後。",trap:"基金に障害給付を付け加える、訴訟の前置を審査会まで引き上げる改変。",e:"基金の老齢年金は付加年金相当額超(法130条2項)。"},
 {id:"XS6-1",s:6,format:"sentaku",sentaku:true,topic:"目的・管掌",difficulty:3,q:"【選択式】国民年金法の目的と管掌 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"国民年金制度は、日本国憲法第25条[[A]]に規定する理念に基き、老齢、障害又は死亡によって国民生活の安定がそこなわれることを[[B]]によって防止し、もって[[C]]の維持及び向上に寄与することを目的とする。国民年金事業は、[[D]]が、管掌する。国民年金事業の事務の一部は、政令の定めるところにより、法律によって組織された共済組合等に行わせることができるほか、[[E]](特別区の区長を含む。)が行うこととすることができる。",blanks:[{key:"A",ok:16,why:"憲法25条1項は生存権そのもの、2項は国の社会保障の向上・増進の努力義務。国民年金法は2項の理念に基づく。",law:"国民年金法1条"},{key:"B",ok:8,why:"社会保険方式の基礎となる考え方。国民年金法1条の中核ワード。",law:"国民年金法1条"},{key:"C",ok:13,why:"「健全な国民生活の維持及び向上に寄与する」が目的規定の結び。",law:"国民年金法1条"},{key:"D",ok:12,why:"国民年金事業の管掌者は政府。日本年金機構は委任・委託を受けて事務を行う立場。",law:"国民年金法3条1項"},{key:"E",ok:9,why:"第1号被保険者の届出の受理などを市町村長が行う(法定受託事務)。",law:"国民年金法3条3項"}],options:["世代間扶養","第13条","文化的な生活","全国健康保険協会","国民の生活水準","国の責任","厚生労働大臣","年金事務所長","国民の共同連帯","市町村長","日本年金機構","社会保険審査官","政府","健全な国民生活","第1項","相互扶助","第2項","都道府県知事","国民の福祉","第3項"],memoryPoint:"国民年金法1条=憲法25条2項+国民の共同連帯。管掌は政府、事務の一部は共済組合等・市町村長。",trap:"憲法25条の「第1項」と「第2項」、管掌者の政府と日本年金機構の入替えが定番。",e:"A=第2項、B=国民の共同連帯、C=健全な国民生活、D=政府、E=市町村長。"},
 {id:"XS6-2",s:6,format:"sentaku",sentaku:true,topic:"障害基礎年金の支給要件",difficulty:3,q:"【選択式】障害基礎年金の支給要件 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"障害基礎年金は、疾病にかかり、又は負傷し、その傷病について初めて医師又は歯科医師の診療を受けた日(以下「[[A]]」という。)において、被保険者であるか、又は被保険者であった者であって日本国内に住所を有し、かつ、[[B]]である者が、当該初診日から起算して[[C]]を経過した日(その期間内にその傷病が治った場合においては、その治った日)(以下「障害認定日」という。)において、その傷病により障害等級に該当する程度の障害の状態にあるときに、その者に支給する。ただし、当該傷病に係る初診日の前日において、当該初診日の属する月の[[D]]までに被保険者期間があり、かつ、当該被保険者期間に係る保険料納付済期間と保険料免除期間とを合算した期間が当該被保険者期間の[[E]]に満たないときは、この限りでない。",blanks:[{key:"A",ok:12,why:"初めて医師又は歯科医師の診療を受けた日。傷病名が確定した日や障害と認定された日ではない。",law:"国民年金法30条1項"},{key:"B",ok:17,why:"被保険者でない者は、国内住所を有する60歳以上65歳未満であることが要件。初診日に被保険者なら住所要件はない。",law:"国民年金法30条1項2号"},{key:"C",ok:5,why:"障害認定日は初診日から1年6月経過日。その前に治れば(症状固定を含む)治った日。",law:"国民年金法30条1項"},{key:"D",ok:7,why:"判定対象は初診日の属する月の前々月まで。初診日の前日時点で判定するため駆け込み納付は不可。",law:"国民年金法30条1項ただし書"},{key:"E",ok:11,why:"納付済期間+免除期間が被保険者期間の3分の2以上。満たさなければ直近1年要件の特例を検討。",law:"国民年金法30条1項ただし書"}],options:["60歳以上70歳未満","受診日","前月","4分の3","傷病確定日","1年6月","2分の1","前々月","当月","3月前","3分の1","3分の2","初診日","65歳以上70歳未満","6月","1年","障害認定日","60歳以上65歳未満","20歳以上60歳未満","2年"],memoryPoint:"初診日要件・障害認定日(1年6月)・納付要件(前日に前々月まで3分の2)。60〜65歳の非被保険者は国内住所が要件。",trap:"「1年6月」と「1年」「6月」、「前々月」と「前月」、「3分の2」と「2分の1」の入替えが狙われる。",e:"A=初診日、B=60歳以上65歳未満、C=1年6月、D=前々月、E=3分の2。"},
 {id:"XS6-3",s:6,format:"sentaku",sentaku:true,topic:"遺族基礎年金の遺族と失権",difficulty:3,q:"【選択式】遺族基礎年金の遺族と失権 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"遺族基礎年金を受けることができる配偶者又は子は、被保険者又は被保険者であった者の配偶者又は子であって、被保険者又は被保険者であった者の死亡の当時その者によって[[A]]し、かつ、次に掲げる要件に該当したものとする。配偶者については、遺族の範囲に該当する子と[[B]]こと。子については、[[C]]に達する日以後の最初の3月31日までの間にあるか又は20歳未満であって障害等級に該当する障害の状態にあり、かつ、現に婚姻をしていないこと。遺族基礎年金の受給権は、受給権者が婚姻をしたとき、又は[[D]]以外の者の養子となったときなどに消滅する。また、障害等級に該当する障害の状態にある子の受給権は、その子が[[E]]に達したときに消滅する。",blanks:[{key:"A",ok:2,why:"死亡者との関係は「生計を維持」(収入要件あり)。",law:"国民年金法37条の2第1項"},{key:"B",ok:19,why:"配偶者と子の関係は「生計を同じくする」。子のない配偶者は受給できない。",law:"国民年金法37条の2第1項1号"},{key:"C",ok:3,why:"18歳到達年度の末日まで。18歳の誕生日に失権するのではない。",law:"国民年金法37条の2第1項2号"},{key:"D",ok:4,why:"夫の父母(直系姻族)などの養子となっても失権しない。",law:"国民年金法40条1項3号"},{key:"E",ok:5,why:"障害状態の子は20歳到達で失権。障害基礎年金の子の加算と同じ年齢。",law:"国民年金法40条3項"}],options:["22歳","15歳","生計を維持","18歳","直系血族又は直系姻族","20歳","同居する","20歳未満","扶養","23歳","同居","3親等内の親族","生計を維持する","扶養する","兄弟姉妹","25歳","6親等内の血族","16歳","生計を同じく","生計を同じくする"],memoryPoint:"配偶者は死者に生計維持+子と生計同一。子は18歳年度末(障害なら20歳未満)・未婚。直系血族・姻族の養子は失権しない。",trap:"「生計を維持」と「生計を同じく」の使い分け、養子の範囲(直系血族・直系姻族)が狙われる。",e:"A=生計を維持、B=生計を同じくする、C=18歳、D=直系血族又は直系姻族、E=20歳。"},
 {id:"XS6-4",s:6,format:"sentaku",sentaku:true,topic:"寡婦年金・死亡一時金",difficulty:3,q:"【選択式】寡婦年金と死亡一時金 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"寡婦年金は、死亡日の前日において死亡日の属する月の前月までの第1号被保険者としての被保険者期間に係る保険料納付済期間と保険料免除期間とを合算した期間が[[A]]以上である夫が死亡した場合において、夫の死亡の当時夫によって生計を維持し、かつ、夫との婚姻関係が10年以上継続した[[B]]未満の妻があるときに、その者に支給する。寡婦年金の額は、死亡日の属する月の前月までの第1号被保険者としての被保険者期間に係る死亡日の前日における保険料納付済期間及び保険料免除期間につき、老齢基礎年金の額の規定の例によって計算した額の[[C]]に相当する額とする。死亡一時金は、第1号被保険者としての被保険者期間に係る保険料納付済期間の月数等が[[D]]以上である者が死亡した場合において、その者に遺族があるときに、その遺族に支給する。死亡一時金を受ける権利は、これを行使することができる時から[[E]]を経過したときは、時効によって消滅する。",blanks:[{key:"A",ok:14,why:"夫の第1号被保険者期間(納付済+免除)が10年以上。第2号・第3号期間は数えない。",law:"国民年金法49条1項"},{key:"B",ok:13,why:"65歳未満の妻に支給。60歳前に受給権を得たときは60歳から65歳までの有期年金。",law:"国民年金法49条1項"},{key:"C",ok:1,why:"夫の第1号期間に基づく老齢基礎年金額の4分の3。付加年金相当額は含まない。",law:"国民年金法50条"},{key:"D",ok:19,why:"保険料納付済期間の月数+一部免除月数の納付割合換算で36月以上。",law:"国民年金法52条の2第1項"},{key:"E",ok:5,why:"死亡一時金を受ける権利の時効は2年。年金給付(5年)と区別する。",law:"国民年金法102条4項"}],options:["70歳","4分の3","2分の1","48月","55歳","2年","10年間","60歳","25年","3年","20年","5年","12月","65歳","10年","5年間","24月","4分の1","3分の2","36月"],memoryPoint:"寡婦年金=夫の第1号期間10年以上・婚姻10年以上・65歳未満の妻・額4分の3。死亡一時金=36月以上・時効2年。",trap:"寡婦年金の「10年」「65歳」「4分の3」、死亡一時金の「36月」「2年」を他の数字と入れ替えてくる。",e:"A=10年、B=65歳、C=4分の3、D=36月、E=2年。"},
 {id:"XS6-5",s:6,format:"sentaku",sentaku:true,topic:"保険料の免除と追納",difficulty:3,q:"【選択式】保険料の免除と追納 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"被保険者が障害基礎年金の受給権者(障害等級1級又は2級)となったときなど法定免除の事由に該当するに至ったときは、その該当するに至った日の属する月の[[A]]からこれに該当しなくなる日の属する月までの期間に係る保険料は、既に納付されたものを除き、納付することを要しない。学生等である被保険者については、[[B]]の前年の所得が一定額以下であるときは、申請により保険料を納付することを要しないものとすることができる(学生納付特例)。保険料の免除等を受けた被保険者又は被保険者であった者([[C]]を除く。)は、厚生労働大臣の承認を受け、承認の日の属する月前10年以内の期間の保険料の全部又は一部につき追納をすることができる。追納は、原則として[[D]]の分から順次に行うものとされ、追納が行われたときは、[[E]]に、追納に係る月の保険料が納付されたものとみなす。",blanks:[{key:"A",ok:4,why:"法定免除は該当するに至った日の属する月の前月から。終期は該当しなくなる日の属する月まで。",law:"国民年金法89条1項"},{key:"B",ok:19,why:"学生納付特例は本人の所得のみで判定。申請免除(本人・配偶者・世帯主)、納付猶予(本人・配偶者)と比較。",law:"国民年金法90条の3"},{key:"C",ok:2,why:"老齢基礎年金の受給権者は追納できない。年金額が確定しているため。",law:"国民年金法94条1項"},{key:"D",ok:3,why:"追納は古い月から順に行うのが原則(学生納付特例期間等についての例外あり)。",law:"国民年金法94条2項"},{key:"E",ok:1,why:"本来の納期に遡って納付されたものとはならない。",law:"国民年金法94条4項"}],options:["承認を受けた日","追納が行われた日","老齢基礎年金の受給権者","先に経過した月","前月","本人及び配偶者","任意加入被保険者","障害基礎年金の受給権者","世帯主","納期限","後に経過した月","当月","前々月","納期限の到来した月","免除を受けた日","65歳以上の者","直近の月","翌月","配偶者","本人"],memoryPoint:"法定免除=前月から非該当月まで。学生特例は本人所得のみ。追納は老齢基礎年金の受給権者は不可、先に経過した月から、追納日に納付みなし。",trap:"法定免除の始期(前月)と終期(該当しなくなる月まで)、学生納付特例の所得判定者を入れ替えてくる。",e:"A=前月、B=本人、C=老齢基礎年金の受給権者、D=先に経過した月、E=追納が行われた日。"},
 {id:"XS6-6",s:6,format:"sentaku",sentaku:true,topic:"被保険者期間と年金の支給期間・時効",difficulty:3,q:"【選択式】被保険者期間と年金の支給 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"被保険者期間を計算する場合には、月によるものとし、被保険者の資格を取得した日の属する月から[[A]]までをこれに算入する。年金給付の支給は、これを支給すべき事由が生じた日の属する月の[[B]]から始め、権利が消滅した日の属する月で終わるものとする。年金給付は、毎年2月、4月、6月、8月、10月及び12月の6期に、それぞれその[[C]]までの分を支払う。年金給付を受ける権利は、その支給すべき事由が生じた日から[[D]]を経過したときは、時効によって消滅し、保険料その他この法律の規定による徴収金を徴収し、又はその還付を受ける権利は、これらを行使することができる時から[[E]]を経過したときは、時効によって消滅する。",blanks:[{key:"A",ok:5,why:"喪失月は算入しない。月内得喪の場合は1か月算入の特例あり。",law:"国民年金法11条1項"},{key:"B",ok:19,why:"支給開始は事由発生月の翌月から。終期は権利消滅月。",law:"国民年金法18条1項"},{key:"C",ok:3,why:"偶数月に前月までの2か月分を支払う。",law:"国民年金法18条3項"},{key:"D",ok:4,why:"年金給付を受ける権利は5年。全額支給停止中は時効が進行しない。",law:"国民年金法102条1項"},{key:"E",ok:2,why:"保険料の徴収権・還付請求権は2年。督促は時効の更新効あり。",law:"国民年金法102条4項"}],options:["当月分","その資格を喪失した日の属する月","2年","前月","5年","その資格を喪失した日の属する月の前月","前々月","2か月","7年","翌月分","60歳に達した日の属する月","当月","翌々月","3年","6月","その資格を喪失した日の属する月の翌月","30年","1年","10年","翌月"],memoryPoint:"被保険者期間=取得月〜喪失月の前月。年金は事由発生の翌月〜消滅月。偶数月に前月分まで。時効は年金5年・保険料2年。",trap:"被保険者期間の終期(喪失月の前月)と年金の支給終期(消滅月)、支払月(前月分まで)の混同が狙われる。",e:"A=その資格を喪失した日の属する月の前月、B=翌月、C=前月、D=5年、E=2年。"}
);
